// Generates Nimbus_Knowledge_Articles.csv — 300+ standard-field-only Knowledge article
// records for the "Ask Nimbus" RAG Agent Workshop. Run with: node generate-articles.js
"use strict";
const fs = require("fs");
const path = require("path");

// ---------- Domains ----------
// Each domain: [ "Domain Label", [ [title, bodyHtml], ... ] ]
// bodyHtml goes into the standard "Summary" (rich text) field.

const P = (s) => `<p>${s}</p>`;
const OL = (items) => `<ol>${items.map((i) => `<li>${i}</li>`).join("")}</ol>`;

const BILLING = [
  ["Understanding Your Invoice", P("Every Nimbus Workspace invoice lists your plan name, billing period, seat count, any add-ons, applicable tax, and the total charged to your payment method on file. Paid plans are billed in advance — monthly plans on the same calendar day each month, annual plans on your subscription anniversary. Line items separate the base subscription cost from add-ons like extra storage or premium integrations, and from any prorated charges caused by mid-cycle seat changes. View or download any invoice from Billing Settings > Invoice History; invoices are also emailed to your billing contact the day they're generated.")],
  ["How Proration Works When You Change Plans", P("When you upgrade or downgrade between Team, Business, and Enterprise mid-cycle, Nimbus Workspace calculates a prorated charge or credit based on the days remaining in your current billing period. Upgrades take effect immediately and the prorated difference is charged right away. Downgrades take effect at the start of your next billing cycle, so you keep current-plan features until then — no partial-period credit is issued for a downgrade. Adding or removing seats mid-cycle follows the same per-seat, per-remaining-day proration logic.")],
  ["Accepted Payment Methods", P("Nimbus Workspace accepts Visa, Mastercard, American Express, and Discover for all self-serve Team and Business plans, charged automatically each billing cycle. Enterprise customers on an annual contract can pay by ACH bank transfer or against a Purchase Order invoice, arranged through your account executive. PayPal, wire transfer for self-serve plans, and cryptocurrency are not supported. Only one payment method can be on file per workspace at a time; adding a new card replaces the previous one for future charges.")],
  ["Updating Your Credit Card on File", P("To update the card charged for your subscription:") + OL(["Go to Billing Settings from your workspace admin console.","Select Payment Method, then Edit.","Enter the new card number, expiration date, and billing zip code.","Click Save — the new card is validated with a $0 authorization check.","Your next scheduled charge, and any future renewals, will use the new card automatically."]) + P("Past invoices are not affected by a payment method change.")],
  ["Why Was I Charged Twice This Month?", P("A duplicate-looking charge is almost always one of three things: a prorated upgrade charge appearing alongside your regular renewal, a failed payment retry that succeeded on a second attempt (the first attempt should show as declined, not charged), or an add-on purchase (extra storage, a premium integration) billed separately from the base subscription. Check Billing Settings > Invoice History — each charge maps to a specific invoice with a line-item breakdown. If two invoices genuinely charge the same line item for the same period, contact Billing Support with both invoice numbers for a refund.")],
  ["Plan Comparison & Switching", P("Nimbus Workspace offers four plans: Free (up to 5 users, 2GB storage), Team ($12/user/month, 50GB pooled storage, automations), Business ($24/user/month, 250GB pooled storage, SSO, advanced reporting), and Enterprise (custom pricing, unlimited storage, SCIM provisioning, dedicated support). To switch plans:") + OL(["Go to Billing Settings > Plan.","Select Compare Plans to see the full feature matrix.","Choose the target plan and click Change Plan.","Review the prorated charge or credit shown before confirming.","Confirm — the change applies immediately for upgrades, or at next renewal for downgrades."])],
  ["Downgrading Your Subscription", P("Downgrades to a lower plan tier take effect at the start of your next billing cycle, not immediately — you keep full access to your current plan's features until then. To downgrade:") + OL(["Go to Billing Settings > Plan > Change Plan.","Select the lower-tier plan.","Review the feature-loss warning (e.g., SSO, advanced reporting are Business/Enterprise-only).","Confirm the scheduled downgrade.","You'll receive a confirmation email with the effective date; you can cancel the scheduled downgrade any time before then."])],
  ["How Seat-Based Billing Works", P("Team and Business plans bill per active user seat. A seat is consumed by any user with Owner, Admin, or Member access; Guest users (view/comment-only on shared projects) do not consume a seat. Your invoice reflects the highest seat count reached during the billing period for monthly plans, or the seat count at contract signing (with a true-up at renewal) for annual and Enterprise plans. Deactivating a user frees their seat for reassignment immediately, but does not generate a mid-cycle refund for that seat.")],
  ["Adding or Removing Seats Mid-Cycle", P("Adding a seat mid-cycle bills a prorated amount for the remaining days in the current period, charged on your next invoice. Removing a seat (by deactivating a user) frees the seat for reassignment immediately but does not issue a prorated credit — the seat count for billing purposes is based on peak usage during the period on monthly plans. Annual and Enterprise contracts true-up seat counts at renewal rather than mid-term, so removing a seat mid-contract reduces cost only at the next renewal.")],
  ["Annual vs. Monthly Billing Cycles", P("Monthly billing charges your card every 30 days at standard per-seat rates. Annual billing charges once per year, up front, at a discounted rate (typically a 15–20% savings versus twelve monthly payments), and is required for Enterprise contracts. You can switch from monthly to annual at any time from Billing Settings — the switch takes effect at your next renewal date and locks in the annual rate. Switching from annual to monthly is only available at the end of your current annual term.")],
  ["Requesting a Refund", P("Annual plan subscribers can request a prorated refund for unused months within 30 days of the renewal charge by contacting Billing Support with their invoice number. Monthly plan charges are non-refundable once processed, but you can cancel at any time to prevent future charges — your access continues through the end of the paid period. Add-on purchases (extra storage, premium integrations) follow the same 30-day annual / non-refundable monthly policy as the base subscription. Approved refunds are returned to the original payment method within 5–7 business days.")],
  ["Understanding Your Free Trial Period", P("New Business and Enterprise plan signups include a 14-day free trial with full feature access and no credit card required to start. A trial banner shows the number of days remaining in your workspace. You can invite teammates, connect integrations, and import data during the trial exactly as on a paid plan — nothing is limited except the trial's duration. Adding a payment method at any point during the trial converts it to a paid subscription immediately and stops the trial countdown.")],
  ["What Happens When Your Trial Ends", P("If no payment method is added before your 14-day trial ends, your workspace automatically converts to the Free plan rather than being deleted. Any data or configuration created beyond Free plan limits (extra seats, storage over 2GB, premium integrations) becomes read-only until you upgrade again — nothing is deleted. You'll receive reminder emails at 7 days, 3 days, and on the final day of your trial with a direct link to add a payment method and continue uninterrupted on your trial plan.")],
  ["Applying a Coupon or Promo Code", P("To apply a promotional code to your subscription:") + OL(["Go to Billing Settings > Plan.","Click Have a promo code?","Enter the code exactly as provided (codes are case-sensitive).","Click Apply — the discount and its expiration, if any, will display before you confirm.","Confirm your plan change or renewal to lock in the discounted rate."]) + P("Only one promo code can be active per workspace at a time; applying a new code replaces the previous one.")],
  ["Tax Exemption Certificates", P("Nonprofit, government, and educational organizations with valid tax-exemption status can submit a certificate to be excluded from sales tax on future invoices. Email your certificate to billing@nimbusworkspace.com along with your workspace ID. Processing takes 3–5 business days, and exemption applies to invoices generated after approval — it is not retroactive to past invoices. Certificates must be renewed with Nimbus Workspace whenever your organization's exemption status is renewed by the issuing authority, typically annually.")],
  ["Multi-Currency Invoicing", P("Self-serve Team and Business plans are billed in USD regardless of your organization's location. Enterprise customers on an annual contract can request invoicing in EUR, GBP, AUD, or CAD through their account executive; the exchange rate is locked at contract signing and re-evaluated at each annual renewal. Multi-currency invoicing is not available for monthly self-serve plans. All invoices, regardless of currency, itemize the same line items — base subscription, add-ons, tax, and any proration.")],
  ["Enterprise Purchase Order (PO) Billing", P("Enterprise customers can pay against a Purchase Order instead of a credit card. To set this up, your account executive issues a formal quote; once you return a signed order form and PO number, Nimbus Workspace generates a NET-30 invoice referencing that PO number. PO-based invoices are sent directly to your accounts payable contact rather than charged automatically. Renewal invoices are generated 45 days before the contract end date to allow time for a new PO to be issued if needed.")],
  ["Downloading Past Invoices as PDF", P("To download a copy of any past invoice:") + OL(["Go to Billing Settings > Invoice History.","Find the invoice by date or invoice number using the search field.","Click the row to expand the line-item detail.","Click Download PDF in the top right of the expanded view.","The PDF includes your company's billing address and tax ID if one is on file, suitable for expense reporting or accounting records."])],
  ["Failed Payment & Dunning Emails", P("If a scheduled charge fails (expired card, insufficient funds, bank decline), Nimbus Workspace retries automatically after 1, 3, and 7 days, sending a dunning email reminder at each attempt with a link to update your payment method. Your workspace remains fully functional during the retry window. If all three retries fail, the workspace is downgraded to a restricted state (read-only for anything beyond Free plan limits) until a valid payment method is added and the outstanding balance is charged.")],
  ["Updating Your Billing Contact", P("The billing contact receives all invoices, payment-failure notices, and renewal reminders — they don't need to be a workspace Admin. To update it, go to Billing Settings > Billing Contact, enter the new name and email address, and click Save. You can also add a secondary billing contact (Business and Enterprise plans only) so notices go to two recipients, useful when finance and IT need visibility into the same billing events.")],
  ["Understanding Add-On Charges", P("Add-ons are billed separately from your base subscription and appear as distinct line items on your invoice. Current add-ons include extra pooled storage blocks (100GB increments), the premium integrations bundle (advanced Jira and GitHub sync), and priority support (guaranteed 4-hour response SLA). Add-ons purchased mid-cycle are prorated like a seat addition; removing an add-on takes effect at your next renewal, consistent with the downgrade policy for the base plan.")],
  ["Understanding Enterprise Custom Pricing", P("Enterprise pricing is quoted per organization based on seat count, contract length, data residency requirements, and any add-ons like SCIM provisioning or a dedicated customer success manager. There is no public list price for Enterprise — request a quote through the in-app Contact Sales link or your account executive. Enterprise quotes typically include volume-based per-seat discounts that improve at higher seat tiers and multi-year commitment discounts for 2- and 3-year terms.")],
  ["Cancelling Your Subscription", P("To cancel your Nimbus Workspace subscription:") + OL(["Go to Billing Settings > Plan.","Click Cancel Subscription at the bottom of the page.","Select a cancellation reason from the short survey (optional but helps us improve).","Confirm cancellation — you'll see the exact date access changes.","Your workspace remains fully functional through the end of the current paid period, then automatically converts to the Free plan; no further charges occur."])],
  ["Reactivating a Cancelled Account", P("If you cancelled and your workspace converted to the Free plan, all your data is preserved and reactivating is immediate:") + OL(["Log in to your workspace as before — cancellation does not lock you out.","Go to Billing Settings > Plan.","Select the plan you'd like to reactivate on.","Enter or confirm your payment method.","Confirm — full plan features are restored immediately, with no re-import needed."]) + P("Workspace data is retained for 90 days after cancellation before any purge, well beyond typical reactivation windows.")],
  ["Volume Discounts for Large Teams", P("Organizations purchasing 100 or more seats on an annual Business or Enterprise plan qualify for tiered volume discounts, ranging from 5% at 100 seats to 20% at 1,000+ seats. Volume pricing is automatically calculated on annual Business plan quotes generated through Contact Sales, and is built into every Enterprise quote by default. Volume discounts apply to the base subscription only, not to add-ons, and require an annual (not monthly) commitment.")],
  ["Non-Profit and Education Discounts", P("Registered nonprofits and accredited educational institutions qualify for a 30% discount off standard Team and Business plan pricing. To apply, submit proof of nonprofit or education status (a 501(c)(3) determination letter, or a .edu domain verification) through Contact Sales. Approved discounts apply at the next renewal and must be re-verified annually. The discount can be combined with annual billing savings but not with other promotional codes.")],
  ["Contract Renewal Notices", P("Annual and Enterprise contracts trigger an automatic renewal notice 60 days before the contract end date, sent to your billing contact and account owner, followed by a second reminder at 30 days. Contracts renew automatically at the then-current rate unless cancelled before the renewal date or a new negotiated rate is in place. Enterprise customers working with an account executive typically begin renewal quote discussions at the 90-day mark to allow time for procurement review.")],
  ["Billing Cycle Start Date Changes", P("Your billing cycle start date is fixed to the day you first subscribed and generally cannot be changed without cancelling and resubscribing, which would forfeit any pro-rated time remaining. Enterprise customers can request a one-time billing-date alignment (for example, to match a fiscal year start) through their account executive; this is handled as a one-time prorated adjustment invoice rather than a plan change, and is available only at contract renewal or upon initial signing.")],
  ["VAT and GST on International Invoices", P("Nimbus Workspace charges VAT, GST, or other applicable sales tax based on your workspace's registered billing country, in compliance with local tax law. If your organization has a valid VAT or GST registration number, add it under Billing Settings > Tax Information — invoices generated afterward will apply the reverse-charge mechanism where applicable, showing 0% tax with your registration number referenced. Adding a tax ID does not affect previously issued invoices.")],
  ["Understanding Usage-Based Overage Charges", P("Storage and API usage on Team and Business plans are pooled allowances, not hard caps — exceeding your plan's included storage or API rate limit doesn't block usage but triggers an overage charge on your next invoice (billed per additional 10GB block for storage; API overages are throttled per FR2.4-style rate limiting rather than billed). Enterprise plans typically negotiate unlimited storage with a fair-use policy instead of overage billing. You can monitor current usage against your plan limits from the Admin Console usage dashboard.")],
  ["Splitting an Invoice Across Departments", P("Business and Enterprise plans support cost-center tagging so a single consolidated invoice can be split for internal chargeback:") + OL(["Go to Billing Settings > Cost Centers.","Create a cost center for each department (e.g., Engineering, Marketing).","Assign each user to a cost center from the Team Directory.","Generate a Cost Center Breakdown report from Billing Settings > Reports.","Export the breakdown as CSV for your finance team — Nimbus Workspace still issues one invoice; the breakdown is informational, not a split billing arrangement."])],
  ["Setting a Spending Limit for Add-Ons", P("Admins can cap how much any user is allowed to spend on self-serve add-ons without additional approval:") + OL(["Go to Billing Settings > Spending Controls.","Toggle on Require approval for add-on purchases.","Set a monthly spending limit per workspace.","Choose which roles can approve requests that exceed the limit (Owner and Admin by default).","Save — any add-on purchase attempt beyond the limit now generates an approval request instead of charging immediately."])],
  ["What's Included in the Enterprise Plan", P("Enterprise includes everything in Business (SSO, advanced reporting, 250GB+ storage) plus SCIM user provisioning, unlimited storage with a fair-use policy, a dedicated customer success manager, a custom Data Processing Agreement, priority support with a 4-hour SLA, single-tenant API keys, and support for a custom data residency region. Enterprise is the only plan tier that supports Purchase Order billing and multi-year contract terms.")],
  ["Free Plan Limitations", P("The Free plan supports up to 5 users, 2GB of pooled file storage, unlimited projects and tasks, and access to the mobile apps, but does not include automations, SSO, advanced reporting, guest access, or API access beyond basic read-only endpoints. Free plan projects can be upgraded to a paid plan at any time with no data migration required — all existing tasks, comments, and files carry over immediately once you upgrade.")],
  ["How to Read Your Billing History", P("Billing Settings > Invoice History lists every invoice in reverse chronological order, showing the date, invoice number, amount, and payment status (Paid, Pending, Failed). Clicking a row expands the full line-item breakdown, including any proration, add-ons, tax, and discounts applied. A Payment Status filter lets you quickly find failed or pending charges, and a date-range filter supports pulling a full year's history for expense reconciliation.")],
  ["Payment Declined — What To Do", P("A declined payment usually means an expired card, insufficient funds, or your bank's fraud filter blocking an unfamiliar merchant charge. First, confirm your card details and expiration date under Billing Settings > Payment Method. If details are correct, contact your card issuer to authorize charges from \"Nimbus Workspace Inc.\" Nimbus Workspace automatically retries a declined charge at 1, 3, and 7 days; you can also trigger a manual retry immediately after updating your payment method rather than waiting for the next scheduled attempt.")],
  ["Switching From Monthly to Annual Billing", P("Switching to annual billing locks in a discounted rate and consolidates twelve payments into one. From Billing Settings > Plan, select Switch to Annual — the change takes effect at your next monthly renewal date, at which point you're charged the full annual amount and your renewal date shifts to a yearly cadence. There's no mid-month proration for this switch; it simply takes effect at the next scheduled renewal.")],
  ["Requesting a Custom Enterprise Contract", P("Organizations needing custom contract terms (a Master Service Agreement, non-standard payment terms, a specific liability cap, or a custom Data Processing Agreement) should work with an account executive rather than self-serve billing:") + OL(["Submit a request via the in-app Contact Sales link, selecting Custom Contract.","An account executive reaches out within 1 business day to scope requirements.","Legal and Security review any requested contract or DPA changes (typically 5–10 business days).","A redlined agreement is circulated for signature via the org's chosen e-signature tool.","Once signed, billing converts to the negotiated terms at the next renewal or immediately, per the contract's effective date."])],
  ["Understanding Seat True-Up at Renewal", P("Annual and Enterprise contracts are priced for a committed seat count at signing. If your actual active-user count exceeds that commitment during the year, a true-up invoice is generated at renewal for the additional seats, prorated for the portion of the year they were active. True-up never happens mid-contract — only at renewal — so adding users during the year doesn't trigger an immediate extra charge, only a reconciliation at the next annual invoice.")],
  ["Billing Support Contact Options", P("Billing questions can be routed through in-app chat (select the Billing topic for fastest routing), email at billing@nimbusworkspace.com, or, for Enterprise customers, directly through your dedicated customer success manager. Standard billing support responds within 1 business day; Enterprise's 4-hour SLA also covers billing inquiries. Have your invoice number or workspace ID ready — it lets support pull up your account immediately without additional verification steps.")],
  ["Gift or Sponsored Subscriptions", P("A third party (a parent company, an accelerator program, or a partner organization) can sponsor a workspace's subscription by being added as an alternate billing contact with payment authorization. Contact Billing Support with written consent from both the workspace owner and the sponsoring party to set this up. Sponsored subscriptions still show standard invoices to the workspace owner for transparency, but charges route to the sponsor's payment method instead.")],
  ["Currency Conversion and Exchange Rate Timing", P("For Enterprise contracts invoiced in a non-USD currency, the exchange rate is locked at the time of contract signing or renewal, not recalculated per invoice — so your per-seat local-currency price stays stable for the full contract term even if exchange rates fluctuate. The rate is re-evaluated only at the next annual renewal, using the prevailing rate at that time, and any change is disclosed in the renewal quote before you commit.")],
  ["Consolidated Billing for Multiple Workspaces", P("Organizations running more than one Nimbus Workspace (for example, separate workspaces per subsidiary) can request consolidated billing through Enterprise sales, which combines all workspaces onto a single invoice and payment method while keeping each workspace's data, users, and admin permissions fully separate. Consolidated billing is configured by Nimbus Workspace's billing operations team and cannot currently be self-served — request it via Contact Sales, referencing all workspace IDs to include.")],
  ["End-of-Life Plan Migration (Legacy Plans)", P("Customers still on a discontinued legacy plan tier (from before the current Free/Team/Business/Enterprise structure) will receive a migration notice at least 90 days before the legacy plan is retired, along with a recommended equivalent current plan and any pricing grandfathering available. No action is required before the notice period ends — if you take no action, your workspace migrates automatically to the recommended plan at the stated date, preserving all existing data and configuration.")],
];

const ACCOUNT = [
  ["Resetting Your Password", P("If you've forgotten your password:") + OL(["Go to the Nimbus Workspace login page and click Forgot Password.","Enter the email address associated with your account.","Check your inbox for a password reset email (arrives within a few minutes).","Click the reset link, which is valid for 60 minutes.","Enter a new password meeting the minimum complexity requirements and confirm."]) + P("If you don't receive the email, check your spam folder or confirm you're using the correct sign-in email — SSO-enabled accounts don't use a Nimbus Workspace password at all.")],
  ["Setting Up Two-Factor Authentication (2FA)", P("To enable 2FA on your account:") + OL(["Go to Account Settings > Security.","Toggle on Two-Factor Authentication.","Choose an authentication method: an authenticator app (TOTP) or SMS text message.","If using an authenticator app, scan the displayed QR code and enter the 6-digit code to confirm.","Save your backup codes somewhere safe — they're the only way back in if you lose access to your authentication method."])],
  ["Adding a Teammate to Your Workspace", P("To invite a new teammate:") + OL(["Go to Team Directory from your workspace admin console.","Click Invite Member.","Enter their email address and select a role (Admin, Member, or Guest).","Optionally assign them to specific projects during invite.","Click Send Invite — they'll receive an email with a link to set up their account."]) + P("Invited users consume a seat as soon as they accept, not at the moment of invitation.")],
  ["Removing a User from Your Workspace", P("To remove a teammate, go to Team Directory, find the user, and select Deactivate from the row's action menu. Deactivating immediately revokes their access and frees their seat for reassignment, but preserves their historical activity (comments, task completions) attributed to their name for audit purposes. Deactivated users can be reactivated later without losing their history. To permanently delete a user's data entirely, use Delete User instead, which is irreversible and typically used only for compliance-driven removals.")],
  ["Understanding User Roles and Permissions", P("Nimbus Workspace has four built-in roles: Owner (full control, including billing and workspace deletion — exactly one per workspace), Admin (manage users, projects, and settings, no billing access by default), Member (create and edit tasks/projects they're added to), and Guest (view and comment only on projects explicitly shared with them, no seat consumed). Business and Enterprise plans additionally support custom roles built from granular permission sets for teams needing finer-grained access control.")],
  ["Creating a Custom Permission Set", P("Business and Enterprise plans can define custom roles beyond the four built-in ones:") + OL(["Go to Team Directory > Roles & Permissions.","Click Create Custom Role.","Name the role and select individual permissions (create projects, delete tasks, manage integrations, view billing, etc.).","Save the role.","Assign it to users from their profile in the Team Directory."]) + P("Custom roles can be edited later; existing users assigned to a role automatically inherit any permission changes.")],
  ["Managing Guest Access", P("Guests are external collaborators given view/comment access to specific shared projects without consuming a paid seat. To invite a guest, open the project, click Share, enter their email, and select Guest as the access level. Guests can comment on tasks and upload files but cannot create new tasks, change project settings, or see other projects in your workspace. Admins can review and revoke all active guest access workspace-wide from Team Directory > Guest Access.")],
  ["Changing Your Account Email Address", P("To change the email address used to sign in, go to Account Settings > Profile, click Change next to your email, and enter the new address. A verification link is sent to the new email; your sign-in email doesn't change until you click that link, which prevents accidental lockouts from a typo. If your account uses SSO, your email is managed by your identity provider and must be changed there rather than in Nimbus Workspace directly.")],
  ["Updating Your Display Name and Avatar", P("Go to Account Settings > Profile to update your display name, profile photo, and job title as shown to teammates across tasks, comments, and mentions. Changes take effect immediately across the workspace, including in past comments (the name shown always reflects your current profile, not a historical snapshot). Profile photos support JPG and PNG up to 5MB; if none is uploaded, initials are shown instead on a colored avatar.")],
  ["Merging Duplicate User Accounts", P("If a teammate accidentally created two accounts (for example, signing up with both a personal and work email), Admins can merge them:") + OL(["Go to Team Directory and identify the duplicate accounts.","Select both accounts and choose Merge Accounts from the bulk action menu.","Choose which account to keep as the primary.","Confirm — all tasks, comments, and project memberships from the secondary account transfer to the primary.","The secondary account is deactivated automatically once the merge completes."]) + P("This action cannot be undone, so confirm the correct primary account before proceeding.")],
  ["Transferring Workspace Ownership", P("Every workspace has exactly one Owner with full billing and deletion authority. To transfer ownership:") + OL(["Go to Team Directory > Workspace Settings.","Select Transfer Ownership.","Choose an existing Admin as the new Owner (the recipient must already have an Admin role).","Confirm — the recipient receives an email they must accept within 7 days.","Once accepted, the previous Owner is automatically reassigned the Admin role."])],
  ["Deactivating vs. Deleting a User", P("Deactivating a user immediately revokes login access and frees their seat, while preserving their name on historical comments, task assignments, and audit logs — this is the recommended default for offboarding. Deleting a user permanently removes their profile information and reassigns their identity in historical records to \"Former User,\" which is irreversible. Use deletion only when required for a specific compliance or data-minimization request, since it removes attribution from your workspace's history.")],
  ["Bulk Inviting Users via CSV", P("To invite many users at once instead of one at a time:") + OL(["Go to Team Directory > Invite Member > Bulk Invite.","Download the CSV template (columns: Email, Role, Project Assignment).","Fill in one row per user and save the file.","Upload the completed CSV.","Review the preview of parsed rows, then click Send Invites — up to 500 rows can be processed in a single upload."])],
  ["Managing User Offboarding", P("When someone leaves your organization, offboard them promptly to protect data and reclaim their seat:") + OL(["Go to Team Directory and locate the departing user.","Reassign any tasks they own to a teammate using the Reassign Tasks action.","Transfer ownership of any projects where they're listed as Project Owner.","Select Deactivate from their row's action menu.","For bulk departures (a layoff or team restructuring), use Bulk Deprovision Users to offboard multiple people in one action — removals affecting more than 25 users require an additional confirmation step."])],
  ["Setting a Default Role for New Members", P("Admins can set which role new invitees receive by default, so inviters don't need to select one manually each time. Go to Team Directory > Workspace Settings > Default Role and choose Member, Admin, or a custom role (Business/Enterprise). This default applies only to future invitations; it does not change the role of anyone already in the workspace. Individual invites can still override the default at the time of sending.")],
  ["Understanding Workspace Admin Privileges", P("Admins can manage users (invite, deactivate, change roles), create and configure projects workspace-wide, manage integrations, and view usage reports, but cannot access billing settings or delete the workspace itself — those remain Owner-only by default. Business and Enterprise plans can grant billing visibility to specific Admins individually via a custom permission set without making them the Owner.")],
  ["Recovering a Locked-Out Account", P("If you're locked out after too many failed login attempts, wait 15 minutes for the automatic lockout to clear, or use the Forgot Password flow to reset your password immediately, which also clears the lockout. If you've also lost access to your 2FA method, use one of your saved backup codes; if those are unavailable too, a workspace Admin can initiate an account recovery from Team Directory > Security > Reset 2FA, which requires identity verification with Nimbus Workspace Support.")],
  ["Session Timeout Settings", P("By default, web sessions time out after 24 hours of inactivity, requiring re-authentication. Business and Enterprise Admins can customize this under Workspace Settings > Security > Session Timeout, choosing any value between 1 and 24 hours, or enabling a shorter timeout specifically for sessions on unrecognized devices. Mobile app sessions persist longer by default (30 days) to avoid repeated logins on trusted personal devices, but can also be tightened by policy on Enterprise plans.")],
  ["Managing Multiple Workspaces Under One Login", P("A single Nimbus Workspace account (one email address) can belong to multiple workspaces — for example, a consultant working across several client organizations. Each workspace maintains entirely separate users, projects, and billing; your role can differ per workspace (Admin in one, Guest in another). There's no limit to how many workspaces one account can belong to, and being added to a new workspace never affects your existing memberships.")],
  ["Switching Between Workspaces", P("If your account belongs to more than one workspace, click your avatar in the top-left corner and select Switch Workspace from the dropdown to see the full list. Selecting a different workspace reloads the app in that workspace's context — your notifications, tasks, and settings are entirely separate per workspace. The mobile app supports the same switcher from the account menu, and remembers your last-used workspace on next launch.")],
  ["Setting Up Single Sign-On (SSO)", P("Business and Enterprise plans support SAML 2.0 SSO with providers like Okta, Azure AD, and Google Workspace:") + OL(["Go to Workspace Settings > Security > Single Sign-On.","Select your identity provider or choose Generic SAML 2.0.","Copy the Nimbus Workspace ACS URL and Entity ID into your identity provider's app configuration.","Upload your identity provider's signing certificate and metadata into Nimbus Workspace.","Enable Enforce SSO once you've tested a successful login, so all users are required to authenticate through your identity provider going forward."])],
  ["Configuring SCIM User Provisioning", P("Enterprise plans support SCIM 2.0 for automated user provisioning and deprovisioning from your identity provider:") + OL(["Go to Workspace Settings > Security > SCIM Provisioning.","Generate a SCIM API token (shown once — store it securely).","Enter the Nimbus Workspace SCIM base URL and token into your identity provider's provisioning app.","Map identity provider groups to Nimbus Workspace roles.","Enable automatic deprovisioning so a user removed from your identity provider is deactivated in Nimbus Workspace within 15 minutes."])],
  ["Setting a Password Policy for Your Organization", P("Business and Enterprise Admins can enforce a minimum password policy for all non-SSO users under Workspace Settings > Security > Password Policy, including minimum length (8–20 characters), required character types (uppercase, number, symbol), and a maximum password age forcing periodic resets (30, 60, or 90 days, or never). Policy changes apply to the next password set by each user; existing passwords aren't invalidated retroactively unless you also enable Force Reset on Next Login.")],
  ["Understanding Login Notifications", P("Nimbus Workspace sends an email notification whenever your account is signed into from a new device or an unrecognized location, including the approximate location, device type, and time. This is separate from 2FA and cannot be disabled for security reasons, though Enterprise Admins can route these notifications to a shared security inbox in addition to the individual user. If you receive a notification for a login you don't recognize, change your password immediately and review Active Sessions.")],
  ["Restricting Login by IP Address", P("Enterprise plans support IP allowlisting to restrict workspace login to specific network ranges — typically a corporate VPN or office IP block. Configure this under Workspace Settings > Security > IP Allowlist by adding CIDR ranges. Once enabled, login attempts from outside the allowlist are blocked before password entry, with an explanatory message. Test the allowlist with a non-Admin account before fully enforcing it, since a misconfigured range can lock out your entire team, including Admins.")],
  ["Managing Pending Invitations", P("Go to Team Directory > Pending Invitations to see everyone who's been invited but hasn't yet accepted, along with the date sent and days remaining before expiration (invitations expire after 14 days). From this list you can resend an invitation, edit the assigned role before it's accepted, or revoke it entirely. Revoking an invitation immediately invalidates the invite link; the invited person will see an expired-invitation message if they try to use it afterward.")],
  ["Resending an Expired Invitation", P("Invitations expire 14 days after being sent if not accepted. To resend one, go to Team Directory > Pending Invitations, find the expired entry (marked with an Expired badge), and click Resend. This generates a fresh invite link with a new 14-day expiration; the original expired link will no longer work. You do not need to re-enter the invitee's email or role — those carry over from the original invitation automatically.")],
  ["Changing a User's Role", P("To change a teammate's role, go to Team Directory, find the user, and select their current role badge to open a dropdown of available roles. Role changes take effect immediately — a Member promoted to Admin gains new permissions on their very next page load, no re-login required. Downgrading a user's role can immediately remove their access to project settings or integrations they previously configured, so review their current responsibilities before downgrading.")],
  ["Viewing Active Sessions", P("Go to Account Settings > Security > Active Sessions to see every device and browser currently signed into your account, including the last-active time, approximate location, and device type. This is useful for confirming no one else is using your account. Each session can be individually revoked, or you can use Sign Out of All Devices to end every session at once, including your current one, requiring you to log back in.")],
  ["Signing Out of All Devices", P("If you suspect unauthorized access, go to Account Settings > Security > Active Sessions and click Sign Out of All Devices. This immediately invalidates every active session, including mobile app sessions and any browser tabs, requiring a fresh login everywhere. It's recommended to also change your password and review recent activity in the audit log immediately after doing this, in case the unauthorized session made any changes.")],
  ["Account Recovery Without Access to Email", P("If you've lost access to both your password and your recovery email, self-service reset isn't possible, since the reset link is the primary verification mechanism. Have a workspace Admin submit an account recovery request through Support on your behalf, providing identity verification (proof of employment or organizational affiliation) as required. Support will work with the Admin to verify your identity and either update your email on file or assist with a supervised password reset.")],
  ["Setting Up a Delegated Admin", P("Owners can grant a trusted teammate Admin-level access without making them a full Admin across every setting, using a delegated admin scope:") + OL(["Go to Team Directory > Roles & Permissions.","Select Add Delegated Admin.","Choose the specific areas they can manage (user management only, integrations only, or a custom combination).","Assign the scope to the chosen user.","They'll see only the delegated sections in Workspace Settings — everything else remains hidden from their view."])],
  ["Understanding Seats vs. Guests", P("A seat is consumed by any Owner, Admin, or Member — these count toward your plan's billed user total. A Guest, by contrast, is an external collaborator with view/comment access to specific shared projects only, and does not consume a seat or count toward billing regardless of how many guests you invite. This distinction lets you collaborate with clients or contractors on specific projects without increasing your subscription cost.")],
  ["Renaming Your Workspace", P("Go to Workspace Settings > General > Workspace Name to rename your workspace. The new name updates immediately across the app, in emails sent to your team, and in the browser tab title. Renaming does not change your workspace's unique URL/subdomain; that requires a separate request through Support since it affects bookmarked links, SSO configuration, and any integrations pointing at the old subdomain.")],
  ["Setting Workspace-Level Default Time Zone", P("Go to Workspace Settings > General > Default Time Zone to set the time zone new users are assigned automatically, used for due dates, calendar sync, and scheduled automations until an individual changes their own profile time zone. Existing users' individually-set time zones are not affected by changing the workspace default; this setting only applies going forward to new members who haven't yet set a personal preference.")],
  ["Managing Notification Preferences", P("Go to Account Settings > Notifications to control which events trigger an email, an in-app notification, or a mobile push — task assignments, @mentions, due-date reminders, comment replies, and project status changes can each be configured independently. A Do Not Disturb schedule can also be set to pause non-urgent notifications outside working hours; @mentions can be exempted from Do Not Disturb individually if you still want to be reachable for direct call-outs.")],
  ["Linking a Google or Microsoft Account for Login", P("Instead of a Nimbus Workspace password, you can sign in using an existing Google or Microsoft account:") + OL(["Go to Account Settings > Security > Linked Accounts.","Select Link next to Google or Microsoft.","Complete the provider's standard OAuth consent screen.","Confirm the link — you can now sign in using either your password or the linked account.","Unlinking is available from the same screen, provided you've set a Nimbus Workspace password as a fallback first."])],
  ["Understanding the Team Directory", P("Team Directory is the central admin view of every user in your workspace, showing their role, status (active, deactivated, pending invite), last login, and project memberships. Admins can filter by role or status, bulk-select users for actions like role changes or deactivation, and export the full directory to CSV for HR or audit purposes. It's also where custom roles, guest access, and pending invitations are managed from a single place.")],
  ["Setting Up Departments or Groups", P("Business and Enterprise plans support organizing users into Departments or Groups for easier bulk management and reporting:") + OL(["Go to Team Directory > Departments.","Click Create Department and name it (e.g., Engineering, Sales).","Add existing users to the department individually or via bulk CSV upload.","Optionally assign a department lead who can manage membership.","Use departments as a filter in reports, cost-center billing, and bulk actions like project assignment."])],
  ["Exporting a List of Active Users", P("Go to Team Directory, apply any filters you want (role, status, department), and click Export CSV in the top right. The export includes name, email, role, status, last login date, and department, useful for HR audits, license reconciliation, or security reviews. Exports reflect a point-in-time snapshot; scheduled recurring exports (daily or weekly, delivered by email) are available on Business and Enterprise plans under Reports > Scheduled Exports.")],
  ["Understanding Inactive User Cleanup Policy", P("Users who haven't logged in for 180 consecutive days are flagged as Inactive in the Team Directory (with a visible badge) but are not automatically deactivated or removed — this is informational only, to help Admins identify stale seats worth reclaiming. Enterprise plans can opt into an automated policy that deactivates (not deletes) users past a configurable inactivity threshold, freeing their seat automatically, with a notification sent to Admins before each automated deactivation.")],
  ["Custom Roles vs. Standard Roles", P("Standard roles (Owner, Admin, Member, Guest) come with a fixed, non-editable set of permissions and are available on every plan. Custom roles (Business and Enterprise only) let you combine individual permissions — such as \"can manage integrations\" or \"can view billing\" — into a role tailored to your team's structure, without granting full Admin access. A user can only hold one role at a time, whether standard or custom.")],
  ["Managing Biometric Login on Mobile", P("The Nimbus Workspace mobile app supports Face ID and fingerprint unlock as a convenience layer on top of your existing login session — it does not replace your password or 2FA, it simply re-authenticates a device that's already signed in without retyping credentials each time. Enable it under the mobile app's Settings > Security > Biometric Unlock. If biometric authentication fails repeatedly, the app falls back to requiring your password.")],
  ["Closing Your Nimbus Workspace Account", P("Closing your entire workspace (not just cancelling a subscription) permanently deletes all projects, tasks, files, and user accounts and cannot be undone. Only the Owner can initiate this:") + OL(["Go to Workspace Settings > General > Close Workspace.","Read the data-loss warning carefully — this is distinct from cancelling a paid plan, which retains data for 90 days.","Type the workspace name to confirm intent.","Confirm closure.","Data is queued for permanent deletion within 30 days, consistent with our standard data retention policy for closed accounts."])],
];

const WORKSPACE = [
  ["Creating Your First Workspace", P("To set up your first Nimbus Workspace:") + OL(["Sign up at nimbusworkspace.com with your email address.","Verify your email via the link sent to your inbox.","Name your workspace (this becomes your workspace URL, e.g., yourcompany.nimbusworkspace.com).","Choose a starting template or begin from a blank workspace.","Invite your first teammates — you can always add more later from Team Directory."])],
  ["Creating Projects from Templates", P("To start a new project from a template instead of blank:") + OL(["Click New Project from any workspace view.","Select Browse Templates.","Choose a category (Marketing, Engineering, Product Launch, Events, etc.) or search by keyword.","Preview the template's included task lists, custom fields, and views.","Click Use This Template — a new project is created pre-populated with the template's structure, ready to customize."])],
  ["Understanding Workspaces vs. Projects vs. Boards", P("A Workspace is your organization's entire account — all users, projects, and billing live under one workspace. A Project is a defined body of work with its own tasks, timeline, and team (e.g., \"Q3 Website Redesign\"). A Board is simply one way of viewing a project's tasks (Kanban-style columns); the same project's tasks can also be viewed as a List, Calendar, or Gantt chart — the underlying tasks are identical across all views, only the presentation changes.")],
  ["Setting Up a Kanban Board", P("Every project defaults to a List view, but you can add a Board view:") + OL(["Open the project and click Add View.","Select Board.","Define your columns (commonly To Do, In Progress, Review, Done) — these map to the task's Status field.","Drag existing tasks into the appropriate column, or create new tasks directly on the board.","Reorder columns by dragging their headers; changes to the board don't affect the List or Gantt views of the same tasks."])],
  ["Switching Between List, Board, and Gantt Views", P("Every project can display its tasks in multiple views simultaneously — List, Board (Kanban), Calendar, and Gantt — accessible from the view tabs at the top of the project. Switching views doesn't change or duplicate your data; it's the same underlying set of tasks rendered differently. Any filter or sort you apply in one view is view-specific and doesn't carry over automatically to the others unless saved as a Saved View.")],
  ["Creating and Assigning Tasks", P("Click + New Task from any project view, enter a task name, and press Enter to create it instantly — additional details (assignee, due date, description, attachments) can be added by clicking into the task afterward. To assign it, click the assignee field and select a teammate from the project's member list; assigning a task automatically adds that person to the project if they weren't already a member, and triggers an assignment notification.")],
  ["Setting Task Dependencies", P("To make one task wait on another:") + OL(["Open the task that should be blocked.","Click Add Dependency.","Select Blocked By and choose the prerequisite task.","Save — the dependent task's due date will show a warning if it's scheduled before the prerequisite's due date.","On the Gantt view, dependencies are shown as connecting lines between tasks, and shifting a prerequisite's date will prompt you to shift dependent tasks accordingly."])],
  ["Creating Subtasks", P("To break a task into smaller steps, open the parent task and click Add Subtask, then enter a name — subtasks appear as a checklist within the parent task and can each have their own assignee and due date. Completing all subtasks does not automatically complete the parent task; the parent must still be marked done explicitly, since a parent task can represent more than just the sum of its subtasks (e.g., a final review step).")],
  ["Setting Up Recurring Tasks", P("To make a task repeat automatically:") + OL(["Open the task and click the due date field.","Select Make Recurring.","Choose a frequency (daily, weekly, monthly, or a custom interval).","Choose whether the next occurrence is created when the current one is marked done, or on a fixed schedule regardless of completion.","Save — a new instance of the task generates automatically according to your chosen rule, keeping the same assignee, description, and subtasks as a copy."])],
  ["Using Milestones to Track Progress", P("Milestones mark significant checkpoints in a project's timeline without being an actionable task themselves — for example, \"Beta Launch\" or \"Contract Signed.\" Add one from the Gantt view by clicking Add Milestone and setting its date; milestones appear as a diamond marker distinct from regular task bars. Milestones can have dependencies just like tasks, so you can require several tasks to complete before a milestone is considered reached.")],
  ["Customizing Task Fields", P("Beyond the default fields (assignee, due date, status, priority), you can show or hide fields per project view by clicking the Fields icon and toggling visibility — this only affects what's displayed, not the underlying data, so hidden fields retain their values and can be re-shown anytime. Reordering fields in this menu also changes their column order in List view and their order on the task detail panel.")],
  ["Creating a Custom Field", P("To add a field beyond the built-in ones:") + OL(["Go to the project's Settings > Fields.","Click Add Custom Field.","Choose a field type (Text, Number, Dropdown, Date, Checkbox, or Person).","Name the field and, for Dropdown fields, define the selectable options.","Save — the field is now available on every task in this project, and can optionally be applied workspace-wide from the same menu if you want it available in all projects."])],
  ["Setting Up Project Templates", P("To turn an existing project into a reusable template:") + OL(["Open the project and go to Project Settings.","Select Save as Template.","Choose whether to include existing task assignees and due dates, or reset them for a clean template.","Name the template and select a category for the template gallery.","Save — the template is now available to your whole workspace under Browse Templates > My Workspace Templates."])],
  ["Duplicating a Project", P("To copy an existing project rather than starting from a template, open the project, click the (···) menu, and select Duplicate Project. Choose whether to carry over task assignees, due dates, comments, and attachments, or reset each independently — for example, keeping the task structure but clearing due dates for a project you're reusing on a new timeline. The duplicate is created as a new project and does not affect the original in any way.")],
  ["Archiving a Completed Project", P("Archiving removes a project from your active project list without deleting it — its tasks, comments, and files remain fully intact and searchable. Open the project, click the (···) menu, and select Archive Project. Archived projects can be restored at any time from Workspace Settings > Archived Projects, or filtered into view from the main project list using the Show Archived toggle.")],
  ["Restoring an Archived Project", P("To bring an archived project back into your active list, go to Workspace Settings > Archived Projects, find the project (searchable by name), and click Restore. The project reappears in the main project list exactly as it was when archived, including all tasks, comments, and views — nothing needs to be reconfigured. There's no limit to how long a project can remain archived before restoration.")],
  ["Deleting a Project", P("Deleting a project (distinct from archiving) permanently removes all its tasks, comments, and attachments after a 30-day recovery window. Only Admins and the Project Owner can delete a project, and a confirmation dialog requires typing the project name to proceed. During the 30-day window, a deleted project can be recovered from Workspace Settings > Trash; after 30 days, it's purged permanently and cannot be recovered by Support.")],
  ["Setting Project Start and Due Dates", P("Go to Project Settings > Timeline to set an overall project start and due date, shown at the top of the Gantt view and used in portfolio-level reporting to flag at-risk projects. Individual task due dates are independent of the project-level dates and are not automatically constrained by them — setting a project due date doesn't prevent a task from having a later date, though the Gantt view will visually flag tasks that extend past the project's end date.")],
  ["Understanding Workload View", P("Workload view shows each team member's assigned tasks across all their projects in a single timeline, color-coded by how many hours or tasks are scheduled per day relative to their configured capacity, helping spot over-allocation before it becomes a bottleneck. Access it from the workspace-level navigation (not inside a single project) under Team > Workload. Capacity per person (hours/day) can be configured individually under their profile in Team Directory.")],
  ["Setting Up Automations (If This, Then That)", P("Automations let a trigger event automatically perform an action without manual steps. To create one:") + OL(["Go to Project Settings > Automations.","Click Create Automation.","Choose a trigger (e.g., \"Status changes to Done\").","Choose an action (e.g., \"Notify project owner\" or \"Move to archive list\").","Save and enable the automation — it applies to all tasks in the project going forward, not retroactively to existing tasks."])],
  ["Creating a Custom Automation Rule", P("Beyond the built-in automation templates, you can build a fully custom rule:") + OL(["Go to Project Settings > Automations > Create Custom Rule.","Define one or more trigger conditions (field changes, due date approaching, comment added).","Add one or more resulting actions, executed in order.","Optionally add a condition branch (if/else) so different actions fire depending on a field's value.","Test the rule using the built-in preview before enabling it live, to confirm it fires as expected."])],
  ["Using Tags and Labels", P("Tags are freeform labels you can attach to any task for cross-cutting organization that doesn't fit neatly into project or status structure — for example, \"urgent,\" \"client-facing,\" or \"needs-design.\" Add a tag from the task detail panel's Tags field; typing a new tag name creates it workspace-wide for reuse. Tasks can be filtered by tag in any view, and a single task can carry multiple tags simultaneously.")],
  ["Filtering and Sorting Tasks", P("Every view supports filtering by assignee, due date range, status, priority, tag, or any custom field, accessible from the Filter icon above the task list. Multiple filters combine with AND logic by default. Sorting is set independently from filtering, via the Sort icon, and supports sorting by due date, priority, creation date, or alphabetically by task name, in ascending or descending order.")],
  ["Setting Up Saved Views", P("A Saved View captures a specific combination of filters, sort order, and view type (List, Board, etc.) so you don't have to reconfigure it each time. After setting up your filters and sort, click Save as View and give it a name — it now appears as a tab alongside the default views for that project. Saved Views can be marked private (visible only to you) or shared with the whole project team.")],
  ["Sharing a Project with External Guests", P("To give an external collaborator access without adding them as a full workspace user:") + OL(["Open the project and click Share.","Enter their email address.","Select Guest as the access level (view and comment only).","Optionally restrict which views or fields are visible to guests.","Send the invite — the guest receives a link to view the shared project without needing a paid seat."])],
  ["Setting Project-Level Permissions", P("Beyond workspace-level roles, individual projects can restrict who can edit versus only view within that specific project, under Project Settings > Permissions. This is useful for sensitive projects (e.g., a compensation planning project) where you want most workspace Members to have no visibility at all, overriding the default that all Members can see all projects. Project-level restrictions never grant more access than a user's workspace-level role allows, only less.")],
  ["Using the Calendar View", P("Calendar view displays tasks by due date in a monthly, weekly, or daily grid, useful for spotting scheduling conflicts and workload clustering. Tasks without a due date don't appear in Calendar view by default, but can be surfaced in an \"Unscheduled\" sidebar for drag-and-drop scheduling directly onto a date. Calendar view respects the same filters (assignee, tag, status) available in List and Board views.")],
  ["Syncing Nimbus Workspace with Google Calendar", P("To sync task due dates with your personal Google Calendar:") + OL(["Go to Account Settings > Integrations > Google Calendar.","Click Connect and complete Google's OAuth consent screen.","Choose which projects' tasks should sync (all projects, or a selected subset).","Choose sync direction: one-way (Nimbus Workspace to Google Calendar) or two-way if you also want date changes made in Google Calendar reflected back.","Save — synced tasks appear as calendar events, refreshing automatically every 15 minutes."])],
  ["Using Time Tracking on Tasks", P("To log time against a task, open it and click the Timer icon to start a live timer, or use Log Time Manually to enter a duration after the fact. Time entries can be tagged as billable or non-billable (Business and Enterprise plans), which feeds into the Time Report for client invoicing or capacity planning. Timers persist across page reloads and continue running until manually stopped, even if you navigate away from the task.")],
  ["Generating a Project Status Report", P("Go to a project's Reports tab and select Status Report to generate a summary of completed vs. remaining tasks, overdue items, and upcoming milestones, formatted for sharing with stakeholders outside the day-to-day project team. Reports can be generated on demand or scheduled to auto-generate and email to a distribution list weekly or monthly. Scheduled reports are a Business and Enterprise feature; on-demand reports are available on all paid plans.")],
  ["Exporting a Project as PDF", P("To export a shareable snapshot of a project:") + OL(["Open the project and click the (···) menu.","Select Export > PDF.","Choose which view to export (List, Board, or Gantt) — the PDF renders that view's current layout.","Choose whether to include comments and attachments references.","Click Generate — the PDF downloads once rendering completes, typically within a few seconds for projects under 500 tasks."])],
  ["Exporting a Project as CSV", P("To export raw task data for spreadsheet analysis or backup:") + OL(["Open the project and click the (···) menu.","Select Export > CSV.","Choose which fields to include (all fields is the default).","Choose whether to include archived/completed tasks.","Click Export — a CSV file downloads with one row per task, including custom fields as additional columns."])],
  ["Setting Up Portfolios (Grouping Projects)", P("Portfolios (Business and Enterprise) group related projects for roll-up reporting — for example, all projects under a single product launch. Go to workspace-level navigation > Portfolios > Create Portfolio, name it, and add existing projects to it. Portfolio view shows an aggregated timeline and status across all included projects, useful for leadership visibility without opening each project individually. A project can belong to more than one portfolio simultaneously.")],
  ["Using the Template Gallery", P("The Template Gallery (accessible from New Project > Browse Templates) includes both Nimbus Workspace's built-in templates across common categories and any custom templates your own workspace has saved. Templates can be previewed before use, showing their default task lists, custom fields, and views. Business and Enterprise plans can also publish templates to a shared internal gallery visible only within your organization, separate from the public built-in set.")],
  ["Importing a Project from Asana", P("To migrate an existing Asana project:") + OL(["Go to Workspace Settings > Import > Asana.","Authorize Nimbus Workspace to access your Asana account via OAuth.","Select which Asana project(s) to import.","Map Asana custom fields to Nimbus Workspace fields, or let auto-mapping handle common field types.","Click Start Import — task names, assignees, due dates, comments, and attachments are migrated; the import can take several minutes for large projects and you'll get a completion notification."])],
  ["Importing a Project from Trello", P("To migrate an existing Trello board:") + OL(["Go to Workspace Settings > Import > Trello.","Authorize access via Trello's OAuth consent screen.","Select the board(s) to import — Trello lists map to Nimbus Workspace Board columns automatically.","Choose whether to import card checklists as Nimbus Workspace subtasks.","Click Start Import — cards, due dates, labels (mapped to tags), and comments are migrated into a new Nimbus Workspace project."])],
  ["Setting Up Custom Statuses", P("Beyond the default To Do / In Progress / Done statuses, you can define custom ones under Project Settings > Statuses — for example, adding \"In Review\" or \"Blocked.\" Each custom status can be assigned a color and marked as a \"completion\" status (counted as done in reports) or not. Reordering statuses here also changes their left-to-right column order in Board view for that project.")],
  ["Understanding Default Task Statuses", P("Every new project starts with three default statuses — To Do, In Progress, and Done — mapped to the standard Board columns and used in default progress reporting. These can be renamed or supplemented with custom statuses, but at least one status must always be marked as a \"completion\" status for progress percentage calculations to work correctly across List, Board, and reporting views.")],
  ["Setting a Project Owner", P("Every project has one designated Owner, distinct from individual task assignees — the Owner is accountable for the project overall and is the default recipient of project-level notifications like status report generation or an approaching project due date. Set or change the Owner from Project Settings > General > Project Owner; only the current Owner or a workspace Admin can reassign it.")],
  ["Using @Mentions in Comments", P("Type @ followed by a teammate's name in any task comment to notify them directly, regardless of whether they're currently assigned to the task. Mentioned users receive an in-app and (per their notification preferences) email or push notification linking straight to the comment. @mentioning someone in a project they don't yet have access to will prompt you to add them to the project before the mention can be sent.")],
  ["Attaching Files to Tasks", P("Drag and drop a file directly onto a task, or click the paperclip icon in the task detail panel to browse and upload. Individual files are capped at 250MB (500MB on Enterprise); attaching a file counts against your workspace's pooled storage allowance. Files can also be attached by linking a Google Drive or Dropbox file via the respective integration, which doesn't count against your storage allowance since the file remains hosted externally.")],
  ["Understanding File Storage Limits", P("Storage is pooled at the workspace level, not per user: Free includes 2GB, Team 50GB, Business 250GB, and Enterprise is unlimited under a fair-use policy. Storage counts files uploaded directly to Nimbus Workspace; files linked from Google Drive or Dropbox via integration don't count against your allowance since they remain hosted externally. Admins can view current usage under Workspace Settings > Storage, broken down by project.")],
  ["Setting Up Dark Mode and Display Preferences", P("Go to Account Settings > Appearance to switch between Light, Dark, and System (matches your device's OS setting) themes. Display density (Comfortable or Compact) can also be set here, controlling row height and spacing in List view for users who prefer to see more tasks on screen at once. These preferences are personal and don't affect what teammates see when viewing the same project.")],
];

const INTEGRATIONS = [
  ["Connecting Nimbus Workspace to Slack", P("To connect Slack:") + OL(["Go to Workspace Settings > Integrations > Slack.","Click Connect and authorize the Nimbus Workspace Slack app in your workspace.","Choose a default channel for workspace-wide notifications.","Optionally connect specific projects to specific channels under each project's Integrations tab.","Save — task assignments, due-date reminders, and @mentions can now post to the configured Slack channels, configurable per notification type."])],
  ["Connecting Nimbus Workspace to Microsoft Teams", P("To connect Microsoft Teams:") + OL(["Go to Workspace Settings > Integrations > Microsoft Teams.","Click Add to Teams and select the target Team and channel.","Authorize the Nimbus Workspace app via Microsoft's consent screen.","Configure which event types (task assignments, comments, due dates) post to the channel.","Save — you can also install the companion Teams tab to view a project's Board directly inside a Teams channel without switching apps."])],
  ["Connecting Nimbus Workspace to GitHub", P("To connect GitHub:") + OL(["Go to Workspace Settings > Integrations > GitHub.","Click Connect and authorize the Nimbus Workspace GitHub App on your organization or selected repositories.","Link a repository to a specific Nimbus Workspace project.","Enable Smart Commits so commit messages referencing a task ID (e.g., \"Fixes NW-142\") automatically update that task's status.","Save — pull request status changes can also be configured to update linked task status automatically."])],
  ["Connecting Nimbus Workspace to Jira", P("To connect Jira:") + OL(["Go to Workspace Settings > Integrations > Jira.","Click Connect and authenticate with your Atlassian account.","Select the Jira project(s) to link.","Configure field mapping between Jira issue fields and Nimbus Workspace task fields.","Choose one-way sync (Jira to Nimbus Workspace) or two-way sync, then save — two-way sync requires webhook configuration in Jira, detailed in the setup wizard's final step."])],
  ["Connecting Nimbus Workspace to Google Drive", P("To connect Google Drive:") + OL(["Go to Account Settings > Integrations > Google Drive.","Click Connect and complete Google's OAuth consent screen.","Once connected, use Attach from Google Drive on any task instead of uploading a file directly.","Linked files show a live preview and open directly in Google Drive when clicked.","Permissions on the linked file are managed in Google Drive itself — Nimbus Workspace does not change the file's sharing settings."])],
  ["Connecting Nimbus Workspace to Zapier", P("To connect Zapier:") + OL(["Go to Workspace Settings > Integrations > Zapier, or search for \"Nimbus Workspace\" directly in Zapier's app directory.","Click Connect a New Account and enter your Nimbus Workspace API token when prompted.","Choose a trigger event (e.g., \"New Task Created\") from the Nimbus Workspace app.","Choose an action in another app (e.g., \"Create a row in Google Sheets\").","Test the Zap and turn it on — Zapier will poll or receive webhook events depending on the trigger type you selected."])],
  ["Getting Started with the Nimbus Workspace API", P("The Nimbus Workspace REST API (v2) lets you programmatically create, read, update, and delete tasks, projects, and users. Base URL is api.nimbusworkspace.com/v2/. All requests require a Bearer token (a personal access token or OAuth app token) in the Authorization header and return JSON. Full endpoint documentation, including request/response schemas, is available at developers.nimbusworkspace.com. Rate limits apply per token — see the API Rate Limits & Quotas article for details.")],
  ["Generating a Personal Access Token", P("To create a token for scripts or personal API use:") + OL(["Go to Account Settings > Developer > Personal Access Tokens.","Click Generate New Token.","Name the token descriptively (e.g., \"Reporting Script\") and select its scopes (read-only, or read/write).","Set an optional expiration date, or choose Never Expires.","Copy the token immediately — it's shown only once and cannot be retrieved again after leaving the page."])],
  ["Creating an OAuth App", P("For integrations serving multiple users, register an OAuth app instead of using a personal token:") + OL(["Go to Workspace Settings > Developer > OAuth Apps.","Click Register New App.","Enter the app name, redirect URI, and requested scopes.","Save to receive a Client ID and Client Secret.","Implement the standard OAuth 2.0 authorization code flow using these credentials — the Client Secret should never be embedded in client-side code."])],
  ["API Rate Limits & Quotas", P("Standard API tokens are limited to 100 requests per minute; Enterprise single-tenant API keys are limited to 500 requests per minute. Exceeding your limit returns an HTTP 429 response with a Retry-After header indicating how many seconds to wait before retrying. Rate limits are tracked per token, not per workspace, so multiple integrations using separate tokens have independent quotas. Sustained 429 responses on an Enterprise account after one retry typically indicate a need for a higher negotiated limit — contact Integration Support.")],
  ["Getting 429 Errors from the API", P("A 429 response means you've exceeded your token's rate limit (100 requests/minute standard, 500/minute Enterprise). Check the Retry-After header returned with the error — it tells you exactly how many seconds to wait. Common causes include polling an endpoint too frequently instead of using webhooks for real-time updates, or running parallel scripts that share the same token. Switching high-frequency polling integrations to webhook-based triggers is the most effective fix, since webhooks don't count against your rate limit the way polling requests do.")],
  ["Understanding API Pagination", P("List endpoints (e.g., GET /v2/tasks) return a maximum of 100 records per page by default, up to 250 if explicitly requested via the limit parameter. Each response includes a next_cursor field in its metadata; pass that value as the cursor query parameter on your next request to retrieve the following page. A null next_cursor indicates you've reached the last page. Cursor-based pagination is used rather than page numbers because it remains stable even if records are added or removed between requests.")],
  ["Understanding API Versioning", P("The current stable API version is v2, reflected in the URL path (api.nimbusworkspace.com/v2/). Breaking changes are only introduced in a new major version, never within v2 itself — non-breaking additions (new optional fields, new endpoints) are added to v2 continuously without requiring migration. The legacy v1 API is deprecated but still functional; see the API Deprecation Policy article for the sunset timeline and migration guidance.")],
  ["API Deprecation Policy", P("When an API version or endpoint is deprecated, Nimbus Workspace guarantees a minimum 12-month sunset window before it's disabled, during which the deprecated version continues to function unchanged. Deprecation notices are posted on the developer changelog and emailed to every workspace with an active token calling the deprecated version, at the start of the window and again 90 and 30 days before sunset. The current v1 API is deprecated with a confirmed sunset date published on the developer portal.")],
  ["Setting Up Webhooks", P("To receive real-time event notifications instead of polling:") + OL(["Go to Workspace Settings > Developer > Webhooks.","Click Add Webhook.","Enter your endpoint URL (must be HTTPS) and select which event types to subscribe to (task created, task updated, comment added, etc.).","Save — a webhook secret is generated for verifying payload authenticity.","Use the Send Test Event button to confirm your endpoint receives and correctly acknowledges a sample payload before relying on it in production."])],
  ["Verifying Webhook Signatures", P("Every webhook payload includes an X-Nimbus-Signature header, an HMAC-SHA256 hash of the raw request body signed with your webhook's secret. To verify authenticity, compute the same HMAC over the raw payload using your stored secret and compare it to the header value using a constant-time comparison function — never a simple string equality check, which can leak timing information. Reject any payload whose computed signature doesn't match; this prevents a third party from forging webhook events to your endpoint.")],
  ["Common Webhook Delivery Failures", P("A webhook delivery fails if your endpoint returns anything other than a 2xx status code within 10 seconds, or if the connection times out entirely. Common causes include a misconfigured firewall blocking Nimbus Workspace's IP range, an endpoint returning a 500 error due to unhandled payload fields, or a slow-responding endpoint exceeding the 10-second timeout. Check Workspace Settings > Developer > Webhooks > Delivery Log for the exact response code and latency of recent delivery attempts.")],
  ["Retrying Failed Webhook Deliveries", P("Failed webhook deliveries are automatically retried up to 5 times with exponential backoff (roughly 1, 5, 30, 120, and 600 seconds after the original attempt). After the fifth failure, the event is marked permanently failed and is not retried further, though it remains visible in the Delivery Log for manual inspection. You can manually trigger a one-off redelivery of any logged event, including permanently failed ones, from the Delivery Log's row-level actions menu.")],
  ["Understanding Webhook Payload Structure", P("Every webhook payload is a JSON object with a top-level event_type field (e.g., task.updated), a timestamp, a data object containing the full current state of the affected record, and, for update events, a changes object listing only the fields that changed along with their old and new values. This lets a receiving integration react to the specific change (e.g., only a status change to Done) without needing to diff the full record itself.")],
  ["Using the Sandbox API Environment", P("Enterprise plans include a full sandbox environment (sandbox-api.nimbusworkspace.com) with isolated data, safe for testing integrations without affecting production tasks or triggering real notifications to teammates. Sandbox tokens are generated separately from production tokens under Workspace Settings > Developer > Sandbox, and sandbox data is reset weekly. Webhooks configured in sandbox only fire for sandbox events and never cross over into your production webhook endpoints.")],
  ["IP Allowlisting for API Access", P("Enterprise plans can restrict API token usage to specific IP ranges (e.g., your server's static outbound IP) under Workspace Settings > Developer > API IP Allowlist. Requests from a token configured with an allowlist, arriving from an IP outside that list, are rejected with a 403 error regardless of whether the token itself is valid. This is independent from the account-login IP allowlist described in Restricting Login by IP Address, and applies specifically to API calls.")],
  ["Understanding OAuth Scopes", P("OAuth apps and personal access tokens request specific scopes limiting what they can access — common scopes include tasks:read, tasks:write, projects:read, projects:write, and users:read. Requesting only the minimum scopes your integration actually needs is strongly recommended; a token with tasks:read cannot create or modify tasks even if the underlying token is compromised. Scopes are fixed at token creation and can only be changed by generating a new token with the desired scope set.")],
  ["Revoking an API Token", P("To revoke a personal access token or OAuth app's access, go to Account Settings > Developer > Personal Access Tokens (or Workspace Settings > Developer > OAuth Apps for an app), find the token or app, and click Revoke. Revocation is immediate — any request using that token fails instantly with a 401 Unauthorized error. Revoking a token does not affect other tokens issued to the same user or app; each token is independent.")],
  ["Rotating API Credentials", P("To rotate a token without downtime, generate a new token with the same scopes before revoking the old one, update your integration or script to use the new token, confirm it's working correctly, and only then revoke the old token. This overlap window avoids an outage that would occur if you revoked first and updated second. Enterprise Client Secrets for OAuth apps can be rotated the same way — Nimbus Workspace supports two active secrets simultaneously during a rotation window.")],
  ["Rate Limit Headers Explained", P("Every API response includes three headers: X-RateLimit-Limit (your token's total requests allowed per minute), X-RateLimit-Remaining (requests left in the current window), and X-RateLimit-Reset (a Unix timestamp for when the window resets). Monitoring X-RateLimit-Remaining proactively, and slowing down before it hits zero, avoids ever receiving a 429 in the first place — this is preferable to a reactive retry-after-429 approach for high-volume integrations.")],
  ["Bulk Data Export via API", P("The GET /v2/export/tasks endpoint generates a full CSV or JSON export of all tasks across specified projects, run asynchronously — the initial call returns a job ID immediately, and you poll GET /v2/export/{job_id}/status until it returns complete with a download URL. This asynchronous pattern is used because full-workspace exports can take several minutes for large accounts and would otherwise exceed typical request timeout limits.")],
  ["Bulk Data Import via API", P("The POST /v2/import/tasks endpoint accepts a batch of up to 500 tasks per request in a single call, validating each row and returning per-row success/failure status rather than failing the entire batch on one bad row. For imports larger than 500 tasks, make sequential batched calls; a common pattern is uploading a CSV client-side, then converting each row into the API's JSON task schema before submitting in batches of 500.")],
  ["Using the Nimbus Workspace CLI", P("The official CLI (installable via npm install -g nimbus-cli) wraps the REST API for common scripting tasks — creating tasks, bulk-tagging, and exporting data from the terminal without writing custom API calls. Authenticate once with nimbus login, which stores a token securely in your local config. Run nimbus --help for the full command list; each command supports a --json flag for scripting output into other tools.")],
  ["Setting Up a Zapier Trigger", P("To use a Nimbus Workspace event as the trigger for a Zap:") + OL(["In Zapier, create a new Zap and search for Nimbus Workspace as the trigger app.","Select a trigger event (New Task, Task Completed, New Comment, etc.).","Connect your Nimbus Workspace account if not already connected.","Select which project to watch, or choose all projects.","Test the trigger to pull a sample record, then continue building your Zap's action steps."])],
  ["Setting Up a Zapier Action", P("To let another app create or update Nimbus Workspace records:") + OL(["In Zapier, add a new action step and search for Nimbus Workspace.","Select an action event (Create Task, Update Task, Add Comment, etc.).","Connect your Nimbus Workspace account if not already connected.","Map fields from the trigger app's data into the corresponding Nimbus Workspace fields.","Test the action to confirm a record is created or updated correctly, then turn on the Zap."])],
  ["Two-Way Sync with Jira", P("When two-way sync is enabled (see Connecting Nimbus Workspace to Jira), a change made in either system propagates to the other within roughly 60 seconds via webhook, not on a polling delay. Field mapping determines which Jira fields correspond to which Nimbus Workspace fields; unmapped fields on either side are simply ignored during sync rather than causing an error. Conflicting simultaneous edits (both systems changed within the same sync window) are resolved by \"last write wins\" based on timestamp.")],
  ["Connecting a Custom Webhook Receiver", P("For integrations not covered by a pre-built connector, use the generic Webhooks feature (see Setting Up Webhooks) to POST event data to any HTTPS endpoint you control, then process the payload with your own backend code however you need — updating a database, triggering a Slack message via your own logic, or feeding a custom analytics pipeline. This is the most flexible integration path, at the cost of requiring you to host and maintain the receiving endpoint yourself.")],
  ["Understanding the REST API Response Format", P("Every successful response returns a JSON object with a data field containing the requested resource or array of resources, and a meta field with pagination info where applicable. Error responses return a consistent shape: an error object with a code (e.g., \"invalid_scope\"), a human-readable message, and, for validation errors, a details array listing the specific field(s) that failed validation, making programmatic error handling straightforward.")],
  ["Handling API Error Codes (400, 401, 403, 404, 500)", P("400 (Bad Request) indicates malformed input — check the error details array for the specific field. 401 (Unauthorized) means your token is missing, expired, or invalid. 403 (Forbidden) means your token is valid but lacks the required scope, or an IP allowlist blocked the request. 404 (Not Found) means the referenced record ID doesn't exist or you lack access to it. 500 (Internal Server Error) is a Nimbus Workspace-side issue — these are rare and automatically logged for investigation; retrying once after a brief delay is reasonable before contacting support.")],
  ["Testing API Calls with Postman", P("A Postman collection covering every v2 endpoint, with example requests and responses, is available at developers.nimbusworkspace.com/postman. Import the collection, then set a collection-level variable for your personal access token so it's automatically included in every request's Authorization header without re-entering it per call. The collection also includes a pre-configured environment for the sandbox API base URL for Enterprise customers testing against sandbox data.")],
  ["API Authentication Methods Overview", P("Two authentication methods are supported: personal access tokens (simplest, tied to one user, best for scripts and personal automation) and OAuth 2.0 (required for apps used by multiple users or distributed publicly, using the standard authorization code flow). Enterprise customers can additionally request single-tenant API keys, which are not tied to any individual user account and are managed centrally by workspace Admins, useful for service-to-service integrations that shouldn't depend on one employee's account.")],
  ["Setting Up Single Tenant API Keys for Enterprise", P("Enterprise workspaces can request a single-tenant API key, which authenticates as the workspace itself rather than an individual user, so integration access doesn't break if the employee who created a personal token leaves the company. Request one through your customer success manager; keys are provisioned with a higher default rate limit (500 requests/minute) and are managed centrally under Workspace Settings > Developer > Enterprise API Keys, visible only to Admins.")],
  ["Monitoring API Usage in the Admin Console", P("Workspace Settings > Developer > API Usage shows request volume per token over the last 30 days, broken down by endpoint and response status code, helping identify which integration is consuming the most quota or generating an unusual rate of errors. Enterprise plans can set usage alert thresholds here, triggering an email to Admins if any token exceeds a configured percentage of its rate limit sustained over a rolling hour.")],
  ["Integration Marketplace Overview", P("Workspace Settings > Integrations lists every available pre-built connector, organized into categories (Communication, Development, File Storage, Automation, Calendar). Each listing shows required plan tier, a setup difficulty estimate, and a link to detailed setup documentation. Business and Enterprise plans unlock additional premium integrations (deeper Jira two-way sync, advanced Salesforce sync) not available on Team or Free plans.")],
  ["Disconnecting an Integration", P("To remove an integration, go to Workspace Settings > Integrations, find the connected app, and select Disconnect. This immediately revokes the stored OAuth token and stops all future syncing, but does not delete any data that was already synced or created as a result of the integration while it was active — for example, previously posted Slack messages or previously imported Jira tasks remain untouched.")],
  ["Troubleshooting a Failed Slack Notification", P("If Slack notifications stop arriving, first check Workspace Settings > Integrations > Slack for a Reconnect Required badge, which appears if the Slack app's OAuth token was revoked (often due to a Slack workspace admin policy change). If the connection shows healthy, confirm the target channel still exists and the Nimbus Workspace Slack app hasn't been removed from that channel — removing the app from a channel silently stops delivery to it without breaking the overall integration connection.")],
  ["Syncing Tasks with Outlook Calendar", P("To sync with Outlook Calendar:") + OL(["Go to Account Settings > Integrations > Outlook Calendar.","Click Connect and complete Microsoft's OAuth consent screen.","Choose which projects' task due dates should sync.","Select one-way or two-way sync.","Save — synced events refresh every 15 minutes and appear in Outlook labeled with the originating Nimbus Workspace project name for easy identification."])],
  ["Understanding Read vs. Write API Scopes", P("Read scopes (e.g., tasks:read) allow retrieving data but never permit creating, updating, or deleting anything, making them the safer default for reporting or monitoring integrations. Write scopes (e.g., tasks:write) allow creating and modifying records and inherently include read access to the same resource type. Always request the narrowest scope combination that satisfies your integration's actual needs — a reporting dashboard, for instance, should never request write scopes.")],
];

const COMPLIANCE = [
  ["Data Deletion & GDPR Requests", P("To request deletion of all personal data associated with your account under GDPR Article 17:") + OL(["Email privacy@nimbusworkspace.com from the email address on file, or ask an Admin to submit the request via Workspace Settings > Privacy > Data Deletion Request.","Nimbus Workspace verifies your identity and organizational authority to make the request.","A confirmation is sent acknowledging receipt within 3 business days.","Deletion is completed within 30 days of a verified request, per our data retention policy.","A final confirmation email is sent once deletion is complete, listing the categories of data removed."])],
  ["Understanding Nimbus Workspace's Data Retention Policy", P("Active workspace data is retained indefinitely while your subscription is active. Deleted tasks and projects remain recoverable in Trash for 30 days before permanent purge. Cancelled workspace data is retained for 90 days post-cancellation to allow reactivation, then permanently purged. Verified GDPR/CCPA deletion requests are honored within 30 days regardless of subscription status, overriding the standard 90-day cancellation retention window.")],
  ["Exporting Your Workspace Data", P("To export a complete copy of your workspace's data (data portability):") + OL(["Go to Workspace Settings > Privacy > Export My Data.","Select the scope: a single project, all projects, or all data including user directory and audit logs.","Choose the export format (CSV for tabular data, or a full JSON archive).","Click Request Export — large exports are processed asynchronously and you'll receive a download link by email, typically within a few hours.","The download link expires after 7 days for security; re-request if needed."])],
  ["Importing Data via CSV", P("To bulk-import tasks from an external CSV:") + OL(["Go to Workspace Settings > Import > CSV.","Download the field-mapping template to see required column headers.","Prepare your CSV with one task per row, matching the template's columns.","Upload the file and review the field-mapping preview, adjusting any auto-mapped columns that look incorrect.","Click Start Import — you'll get a summary of rows imported successfully versus any that failed validation, with reasons listed per failed row."])],
  ["Understanding CCPA Opt-Out Requests", P("California residents can exercise their CCPA right to opt out of the sale or sharing of personal information by submitting a request through Workspace Settings > Privacy > CCPA Request, or by emailing privacy@nimbusworkspace.com with \"CCPA Opt-Out\" in the subject line. Nimbus Workspace does not sell personal information as defined under CCPA in the ordinary course of business; opt-out requests are still honored and confirmed in writing within 15 business days as required by law.")],
  ["Requesting a Copy of Your Data (Data Portability)", P("Under GDPR Article 20 and similar data portability rights, you can request a machine-readable copy of your personal data. Submit the request via Workspace Settings > Privacy > Export My Data, selecting the JSON format for full portability, or contact privacy@nimbusworkspace.com directly if you need a custom scope. This is functionally the same export mechanism used for general workspace backups, but tracked and confirmed as a formal data-subject request when submitted through the Privacy menu.")],
  ["Understanding Data Residency Options (US vs. EU)", P("By default, all workspace data is stored in Nimbus Workspace's US region data centers. Business and Enterprise plans can opt into EU data residency at signup or by request through Support, which stores all workspace data (tasks, files, user records) exclusively in EU-based infrastructure. Data residency cannot be changed after a workspace is created without a full data migration, coordinated with Support, since it involves physically relocating stored data between regions.")],
  ["Requesting a SOC 2 Report", P("Nimbus Workspace maintains a SOC 2 Type II report, renewed annually, covering security, availability, and confidentiality trust principles. Business and Enterprise customers can request the current report under NDA through Workspace Settings > Compliance > Request SOC 2 Report, or via your account executive. The report is typically delivered within 2 business days after the NDA is countersigned through our standard e-signature workflow.")],
  ["Requesting a Penetration Test Summary", P("An executive summary of Nimbus Workspace's most recent third-party penetration test (conducted at least annually) is available to Business and Enterprise customers under NDA, covering methodology and high-level findings without disclosing exploitable technical detail. Request it the same way as the SOC 2 report, through Workspace Settings > Compliance > Request Security Documentation, or through your account executive for Enterprise accounts.")],
  ["Understanding Nimbus Workspace's Sub-Processor List", P("A current list of all third-party sub-processors (cloud infrastructure providers, email delivery services, analytics tools) that may process customer data on Nimbus Workspace's behalf is published at nimbusworkspace.com/subprocessors and updated whenever a new sub-processor is added. Enterprise customers with a signed Data Processing Agreement can subscribe to email notifications of sub-processor changes, with a minimum 30-day notice before a new sub-processor begins processing their data.")],
  ["Data Processing Agreement (DPA) Overview", P("Nimbus Workspace's standard Data Processing Agreement, compliant with GDPR Article 28 requirements, is available to all Business and Enterprise customers and can be countersigned electronically through Workspace Settings > Compliance > Data Processing Agreement without needing to involve an account executive. Enterprise customers requiring custom DPA terms (specific sub-processor restrictions, custom audit rights) should route the request through Legal via their account executive instead of the self-serve flow.")],
  ["Understanding Backup and Restore Policy", P("Nimbus Workspace performs automated encrypted backups of all workspace data every 24 hours, retained for 35 days on a rolling basis. Backups are used for disaster recovery (restoring service after an infrastructure failure) and are not directly customer-accessible as a self-service restore point — for accidental data loss within your own workspace, use the 30-day Trash recovery window instead, which is faster and self-service.")],
  ["Exporting an Audit Trail", P("Business and Enterprise plans include an audit log tracking security-relevant events (logins, permission changes, data exports, integration connections). To export it, go to Workspace Settings > Security > Audit Log, apply any date-range or event-type filters, and click Export CSV. Audit log entries are retained for 12 months by default; Enterprise customers can request an extended retention period of up to 7 years for regulatory compliance.")],
  ["Understanding the Audit Log Feature", P("The audit log records who did what and when for security-sensitive actions: logins (including failed attempts), role changes, user deactivation, data exports, integration connections/disconnections, and changes to security settings like SSO or IP allowlisting. Regular task and project activity (creating a task, changing its status) is not part of the security audit log — that's tracked separately in each task's own activity history, viewable from the task detail panel.")],
  ["Setting a Custom Data Retention Schedule (Enterprise)", P("Enterprise customers with specific regulatory retention requirements can configure a custom retention schedule (e.g., auto-purge completed tasks after 3 years) under Workspace Settings > Compliance > Retention Schedule. This is configured jointly with Nimbus Workspace's compliance team to ensure the schedule doesn't conflict with active legal holds, and typically requires a brief onboarding call to confirm the specific regulatory framework driving the requirement.")],
  ["Deleting a Workspace and Its Data", P("See Closing Your Nimbus Workspace Account for the full closure procedure. From a compliance standpoint: closure queues all workspace data for permanent deletion within 30 days, consistent with standard retention policy, and this cannot be expedited faster than 30 days even upon request, since it aligns with our standard secure-deletion verification process across backup systems.")],
  ["Understanding What Happens to Data After Cancellation", P("Cancelling a subscription (converting to Free plan) is distinct from closing the workspace entirely — cancellation retains all data for 90 days in case you reactivate, with anything over Free plan limits (extra seats, storage, premium integrations) becoming read-only rather than deleted. Only a full workspace closure, a separate and explicit action, queues data for permanent deletion, and that happens within 30 days rather than 90.")],
  ["Requesting Data Deletion for a Departed Employee", P("To remove a specific former employee's personal data (rather than closing the whole workspace) under GDPR/CCPA:") + OL(["Have a workspace Admin deactivate the user first via Team Directory, if not already done.","Submit a Data Deletion Request via Workspace Settings > Privacy, specifying the individual user rather than the full account.","Nimbus Workspace verifies the request comes from an authorized Admin.","Personal identifying information is removed and historical records are reattributed to \"Former User\" within 30 days.","Task content and comments they authored remain (as workspace business records) unless separately flagged for removal."])],
  ["Bulk Exporting Attachments and Files", P("To export all files attached across your workspace (not just task data), go to Workspace Settings > Privacy > Export My Data, select Include Attachments, and choose Full JSON Archive as the format. Large workspaces with many files may take several hours to package; you'll receive a download link by email once ready, valid for 7 days, delivered as a single compressed archive organized by project folder.")],
  ["Understanding HIPAA Applicability", P("Nimbus Workspace is not designed or certified for storing Protected Health Information (PHI) and does not sign Business Associate Agreements for standard Team or Business plans. Enterprise customers in healthcare-adjacent industries who need to discuss HIPAA-aligned controls or a BAA should contact their account executive — support for regulated healthcare data requires specific contractual and technical arrangements evaluated on a case-by-case basis, not available as a standard feature.")],
  ["Understanding Data Encryption at Rest and in Transit", P("All data at rest is encrypted using AES-256; all data in transit between your browser or API client and Nimbus Workspace's servers is encrypted using TLS 1.2 or higher, with older TLS versions rejected outright. Encryption keys are managed through a dedicated key management service with automatic annual rotation. This applies uniformly across all plan tiers — encryption is not an Enterprise-only feature.")],
  ["Configuring Data Loss Prevention Settings", P("Enterprise plans support basic Data Loss Prevention controls under Workspace Settings > Compliance > DLP, including restricting file attachment types, disabling external sharing/guest access workspace-wide, and blocking bulk export for non-Admin roles. These controls are additive restrictions on top of standard role permissions — they can only make the workspace more restrictive, not grant additional access beyond what a role already allows.")],
  ["Understanding Cross-Border Data Transfer Safeguards", P("For customers whose data is processed across regions (for example, a US-headquartered company with EU-based team members on a US-region workspace), Nimbus Workspace relies on Standard Contractual Clauses incorporated into our Data Processing Agreement as the transfer safeguard mechanism, consistent with current GDPR guidance following the invalidation of prior transfer frameworks. Customers requiring data to remain strictly within one region should use the EU Data Residency option instead of relying on transfer safeguards.")],
  ["Requesting an Incident History Report", P("A history of any past security incidents affecting customer data (if any) that met the disclosure threshold under our incident response policy is available to Business and Enterprise customers on request through Workspace Settings > Compliance > Security Documentation. Material incidents affecting a specific customer's data are also proactively disclosed directly to that customer's Admins, separate from this on-request historical summary.")],
  ["Understanding the Status Page and Uptime SLA", P("Real-time system status and historical uptime is published at status.nimbusworkspace.com, including incident post-mortems for any outage affecting core functionality. Business and Enterprise contracts include a 99.9% monthly uptime SLA with defined service credits for shortfalls, detailed in the Master Service Agreement. Subscribe to status.nimbusworkspace.com directly for email or SMS alerts on new incidents, independent of your Nimbus Workspace login.")],
  ["Reviewing the Subprocessor Change Notification Policy", P("Enterprise customers with a signed DPA can opt into advance email notification whenever a new sub-processor is added to Nimbus Workspace's published sub-processor list, with a minimum 30-day notice before the new sub-processor begins processing data, giving time to object per the DPA's objection procedure if needed. Opt in under Workspace Settings > Compliance > Sub-Processor Notifications; this is off by default and must be explicitly enabled per workspace.")],
  ["Setting Up Legal Hold on a Workspace", P("Enterprise customers involved in litigation or a regulatory investigation can request a Legal Hold on specific projects or the entire workspace, which suspends the standard data retention and deletion schedule (including the 30-day Trash purge) for the held scope until the hold is lifted. Legal Holds are configured jointly with Nimbus Workspace's Legal team — request one through your account executive, providing the scope and expected duration if known.")],
  ["Exporting Data for eDiscovery", P("For eDiscovery requests, Enterprise customers can request a comprehensive export including task content, comments, attachments, and full audit log history within a specified date range, formatted for legal review platforms. This differs from the standard self-service export in that it includes deleted/archived items still within retention and is fulfilled directly by Nimbus Workspace's compliance team rather than the self-service Export My Data flow — request it through your account executive or privacy@nimbusworkspace.com.")],
  ["Understanding Consent Management for Guest Users", P("Guest users invited to a shared project are shown a brief consent notice on first access, describing what data (their name, email, and any comments they post) will be visible to the inviting workspace. Guests can decline and are not granted access if they do not consent. Workspace Admins can review a log of guest consent events under Workspace Settings > Privacy > Guest Consent Log.")],
  ["Data Minimization Practices at Nimbus Workspace", P("Nimbus Workspace collects only the data needed to provide the service — account profile information, task/project content you create, and standard operational logs (login times, API usage) needed for security and billing. We do not sell personal data or use customer task content to train shared AI models without explicit opt-in; any AI features process content in the context of your own workspace only.")],
  ["Understanding Cookie and Tracking Policy", P("Nimbus Workspace uses essential cookies required for login sessions and security (cannot be disabled without breaking core functionality) and optional analytics cookies used to understand product usage patterns, which can be disabled from the cookie consent banner or later under Account Settings > Privacy > Cookie Preferences. A full list of cookies in use, their purpose, and retention period is published at nimbusworkspace.com/cookie-policy.")],
  ["Requesting Account Data Anonymization", P("As an alternative to full deletion, you can request anonymization of your personal data instead — your name and email are replaced with a generic identifier across historical records (comments, task assignments) while preserving the business record itself for workspace continuity. Request this via privacy@nimbusworkspace.com, specifying anonymization rather than deletion; note this is irreversible, same as deletion, once processed.")],
  ["Understanding Children's Data Policy (COPPA)", P("Nimbus Workspace is a business productivity tool intended for users 16 years of age or older and is not directed at children; we do not knowingly collect personal information from children under 13 in a manner requiring COPPA compliance. If we become aware that a child's data has been collected without appropriate consent, it is deleted promptly upon verification — report any such concern to privacy@nimbusworkspace.com.")],
  ["Reviewing the Acceptable Use Policy", P("The Acceptable Use Policy, published at nimbusworkspace.com/aup, prohibits using Nimbus Workspace to store or transmit illegal content, malware, or content that infringes third-party intellectual property, and prohibits attempts to circumvent rate limits, security controls, or seat-based billing through technical workarounds. Violations can result in content removal, account suspension, or termination depending on severity, as outlined in the full policy.")],
  ["Understanding the Privacy Shield / Data Transfer Framework Status", P("Following the evolution of EU-US data transfer frameworks, Nimbus Workspace relies primarily on Standard Contractual Clauses (incorporated in our DPA) as the mechanism for lawful cross-border transfer, and additionally participates in the current EU-U.S. Data Privacy Framework where applicable as a supplementary safeguard. Current certification status is published at nimbusworkspace.com/data-transfer and updated as the regulatory landscape evolves.")],
  ["Setting Data Export Permissions for Admins Only", P("By default, any Member can export the projects they have access to. Business and Enterprise Admins can restrict bulk data export (CSV/JSON export of tasks or the full workspace) to Admin and Owner roles only, under Workspace Settings > Compliance > DLP > Restrict Data Export. This does not affect individual file downloads (opening a single attachment), only bulk export functionality.")],
  ["Scheduling Automated Data Exports", P("To set up a recurring backup export without manually triggering it each time:") + OL(["Go to Workspace Settings > Privacy > Scheduled Exports.","Click Create Scheduled Export.","Choose the scope (all projects, or a specific subset) and format (CSV or JSON).","Set a frequency: daily, weekly, or monthly.","Choose delivery: email link, or (Enterprise) automatic delivery to a connected S3 bucket or SFTP endpoint for long-term archival outside Nimbus Workspace."])],
  ["Understanding Retention of Deleted Tasks and Projects", P("Deleted tasks and projects move to Trash and remain recoverable for exactly 30 days, after which they are permanently purged from both production storage and, within an additional 35 days, from the encrypted backup rotation as well. There is no way to recover data past the 30-day Trash window through self-service or Support — this window is intentionally firm to keep the stated retention policy accurate and auditable.")],
  ["Requesting a Business Associate Agreement (BAA)", P("As noted under Understanding HIPAA Applicability, Nimbus Workspace does not offer a standard BAA for Team or Business plans. Enterprise customers in healthcare-adjacent contexts who believe they need a BAA should raise this with their account executive early in the sales process, since it requires a dedicated technical and contractual review to confirm whether Nimbus Workspace's current architecture can support the required safeguards for that specific use case.")],
  ["Understanding Log Retention for Security Events", P("Security-relevant logs (login attempts, authentication events, admin actions) are retained for 12 months by default across all plans, and are the basis for the Audit Log feature. Enterprise customers can request extended retention up to 7 years for regulatory purposes, configured under Workspace Settings > Compliance > Retention Schedule alongside other custom retention settings.")],
  ["Migrating Data Between Workspaces", P("To move projects from one Nimbus Workspace account to another (for example, after a company divestiture):") + OL(["Export the source workspace's data using Export My Data with the Full JSON Archive format.","Have an Admin on the destination workspace go to Workspace Settings > Import > Nimbus Workspace Archive.","Upload the exported archive file.","Map any users who should be re-invited to the destination workspace versus left unassigned.","Start the import — this is a copy operation, so the source workspace's data is unaffected and remains until you separately choose to delete or archive it there."])],
  ["Understanding the Right to Rectification Process", P("Under GDPR Article 16 and similar rights, you can request correction of inaccurate personal data held about you. Most profile information (name, email, job title) can be corrected directly under Account Settings > Profile without a formal request. For data you cannot self-correct (for example, historical audit log entries), submit a request to privacy@nimbusworkspace.com describing the inaccuracy; corrections to historical records are evaluated case by case to balance accuracy against record-integrity requirements.")],
];

const TROUBLESHOOTING = [
  ["Mobile App Troubleshooting", P("If the mobile app is behaving unexpectedly, work through these steps in order:") + OL(["Confirm you're on the latest app version from the App Store or Google Play — many issues are fixed in the most recent release.","Force-close the app completely and reopen it.","Check your internet connection; switch between Wi-Fi and cellular data to isolate a network-specific issue.","Log out and log back in to refresh your session.","If the issue persists, reinstall the app entirely — this clears any corrupted local cache without affecting your account data, which is stored server-side."])],
  ["Mobile App Keeps Crashing on iOS", P("For repeated crashes specifically on iOS:") + OL(["Confirm your iOS version is 16 or later — older versions are no longer supported by the current app build.","Update the Nimbus Workspace app from the App Store to the latest version.","Restart your iPhone or iPad completely (not just the app).","Free up storage space — iOS can terminate apps abnormally when device storage is critically low.","If crashes continue, delete and reinstall the app, then report the crash to Support with your device model and iOS version for investigation."])],
  ["Mobile App Keeps Crashing on Android", P("For repeated crashes specifically on Android:") + OL(["Confirm your Android version is 10 or later.","Update the app via Google Play to the latest version.","Go to Android Settings > Apps > Nimbus Workspace > Storage and clear the app cache (not app data, which would log you out).","Restart your device.","If crashes continue, note your exact device model and Android version and contact Support — some crashes are manufacturer-specific and require targeted investigation."])],
  ["Nimbus Workspace Won't Load in Chrome", P("If the app fails to load or shows a blank page in Chrome, clear your browser cache and cookies for nimbusworkspace.com specifically (Settings > Privacy > Clear Browsing Data, scoped to this site), then reload. Disable browser extensions one at a time, particularly ad blockers or script blockers, since these occasionally block required assets. Confirm you're on a supported Chrome version (the current version or one major version behind). If the issue persists across a different browser too, it's likely network- or account-related rather than browser-specific — contact Support.")],
  ["Fixing a Blank Screen After Login", P("A blank screen immediately after login is most commonly a stale cached JavaScript bundle conflicting with a recent app update. Try a hard refresh (Ctrl+Shift+R on Windows, Cmd+Shift+R on Mac) before anything else. If that doesn't resolve it, clear your browser's cache for the site and reload. Check status.nimbusworkspace.com for any active incident affecting page load. If the blank screen persists after these steps, try an incognito/private window to rule out a corrupted local session.")],
  ["Notifications Not Showing Up", P("First confirm your notification preferences under Account Settings > Notifications haven't been narrowed to exclude the event type you expected (task assignment, mention, etc.). Check that Do Not Disturb isn't currently active. On mobile, confirm push notifications are enabled both in the Nimbus Workspace app settings and at the OS level (iOS Settings > Notifications, or Android equivalent) — an OS-level permission revoked outside the app silently blocks delivery without any error shown in-app.")],
  ["Email Notifications Not Being Received", P("If email notifications aren't arriving, check your spam or junk folder first — automated notification emails are occasionally filtered by aggressive corporate spam filters. Confirm your notification preferences under Account Settings > Notifications have email enabled for the relevant event type. If your organization uses an email allowlist, ask IT to allowlist notifications@nimbusworkspace.com. If only some notification types are missing while others arrive normally, the issue is almost always a preference setting rather than a delivery problem.")],
  ["Slow Performance on Large Projects", P("Projects with several thousand tasks can experience slower List or Board view rendering, particularly with many custom fields displayed simultaneously. To improve performance: apply a filter to reduce the visible task count, hide unused custom field columns, and consider archiving completed tasks older than a defined threshold rather than keeping them in the active view indefinitely. Gantt view is the most performance-sensitive view for very large projects; List view with filters applied is typically fastest for day-to-day work on large projects.")],
  ["Files Won't Upload", P("If a file upload fails, first confirm it's under the 250MB size limit (500MB on Enterprise) — oversized files fail silently in some browsers rather than showing a clear error. Check your internet connection stability, since large uploads that lose connection partway don't automatically resume. Confirm the file type isn't blocked by a workspace-level Data Loss Prevention restriction on attachment types, if your organization has one configured. Try a different browser to rule out a browser-specific upload handling issue.")],
  ["Comments Not Saving", P("If a comment appears to submit but doesn't persist after refresh, this is most often a network interruption during submission — check for a brief \"Sending...\" indicator that never resolves to \"Sent,\" which confirms a connectivity issue rather than a bug. Try again on a stable connection. If comments consistently fail to save even on a stable connection, clear your browser cache, since a stale cached version of the app can occasionally mishandle the comment submission request format after an update.")],
  ["Task Assignment Not Working", P("If assigning a task to a teammate doesn't seem to take effect, confirm the person is actually a member of that specific project — you cannot assign a task to someone without project access, and the assignee dropdown will only show valid candidates, though occasionally a cached member list can show someone who was since removed. Refresh the page to reload the current member list, then try the assignment again. If the assignee field reverts to unassigned after saving, check whether an automation rule on the project is unintentionally clearing the assignee field on certain triggers.")],
  ["Calendar Sync Not Updating", P("If Google or Outlook Calendar isn't reflecting recent Nimbus Workspace task changes, remember sync runs on a 15-minute refresh interval, not instantly — wait at least that long before troubleshooting further. If it's been longer than 15 minutes, check Account Settings > Integrations for a Reconnect Required badge, which appears if the calendar provider's access token expired or was revoked. Reconnecting re-authorizes access and typically resolves a stalled sync immediately on the next scheduled run.")],
  ["Search Not Returning Expected Results", P("Nimbus Workspace search indexes task titles, descriptions, and comments, but newly created or edited content can take up to 2 minutes to appear in search results due to indexing delay — this is expected, not a bug. Confirm you're searching within the correct scope (a single project versus workspace-wide, toggled at the top of the search results panel). If a specific task never appears in search even after several minutes, confirm you actually have access to the project it belongs to, since search never surfaces content you can't otherwise view.")],
  ["Gantt Chart Not Rendering Correctly", P("Gantt rendering issues (overlapping bars, missing dependency lines) are most often caused by tasks with conflicting or missing dates — a task with a due date earlier than its start date, for example, can render unpredictably. Review tasks flagged with a date-conflict warning icon in List view and correct their start/due dates. If the chart still renders incorrectly after fixing date conflicts, try a hard browser refresh, since Gantt view caches layout calculations client-side for performance.")],
  ["Automation Rule Not Triggering", P("If an automation doesn't fire as expected, first confirm it's actually enabled — automations can be toggled off without being deleted, and a disabled rule shows greyed out under Project Settings > Automations. Next, verify the trigger condition precisely matches what you did (for example, a trigger set to \"Status changes to Done\" won't fire if you deleted the task instead of completing it). Automations also don't run retroactively on existing tasks — they only fire on changes that happen after the automation was enabled.")],
  ["Time Tracking Timer Not Stopping", P("If a time tracking timer appears stuck running, it may simply be running on a different device or browser tab than the one you're currently viewing — timers are tied to your account, not a specific device, and only one can run at a time per user. Check Account Settings > Time Tracking > Active Timer to see and stop it from any device. If a timer shows as running but you're certain you stopped it earlier, refresh the page — this is typically a display caching issue rather than the timer actually still running server-side.")],
  ["Unable to Drag and Drop Tasks", P("Drag-and-drop reordering (in Board or List view) requires JavaScript to be fully loaded and can fail silently if a browser extension is interfering with pointer events — try disabling extensions, particularly ad blockers, one at a time. Drag-and-drop is also disabled for users with Guest-level access, by design, since guests cannot modify project structure. Confirm your role has edit permission on the project if reordering consistently fails only in one specific project.")],
  ["Offline Mode Not Syncing Changes", P("Changes made in the mobile app while offline are queued locally and sync automatically once connectivity returns — this can take up to a minute after reconnecting, not instantly. If changes still haven't synced after several minutes on a confirmed stable connection, open the app's Sync Status screen (Settings > Sync Status) to see any pending items and their error state. A sync conflict (the same task edited both offline and by someone else online) will show a manual resolution prompt rather than silently discarding either version.")],
  ["App Stuck on Loading Screen", P("If the app hangs indefinitely on its initial loading screen, check status.nimbusworkspace.com first for an active incident. If status is normal, force-close and reopen the app (mobile) or hard-refresh the browser tab (web). Confirm your device's date and time are set correctly and set to automatic — an incorrect system clock can cause authentication token validation to fail silently, presenting as a stuck loading state rather than a clear error message.")],
  ["Login Loop After Entering Password", P("A login loop (returning to the login page repeatedly after a seemingly successful password entry) is most often caused by third-party cookies being blocked in your browser, which breaks the session token handoff. Enable cookies for nimbusworkspace.com specifically, or check your browser's tracking-prevention settings if using Safari or Firefox in a strict privacy mode. If you're on an SSO-enabled workspace, a login loop can also indicate a misconfigured identity provider assertion — contact your workspace Admin to review the SSO configuration.")],
  ["Two-Factor Authentication Code Not Working", P("If your 2FA code is rejected, first confirm your device's clock is set to automatic network time — TOTP codes are time-based and even a few minutes of drift will produce an invalid code. Confirm you're reading the current code and not one that already expired (codes rotate every 30 seconds). If using SMS-based 2FA, confirm you have signal and haven't blocked the sending number. If none of these resolve it, use a saved backup code to log in, then re-set up 2FA from scratch.")],
  ["Browser Compatibility Issues", P("Nimbus Workspace officially supports the current and previous major versions of Chrome, Firefox, Safari, and Edge. Internet Explorer is not supported and will show a persistent compatibility warning banner. If you experience layout glitches or broken functionality, first confirm your browser version meets the minimum supported version before troubleshooting further, since older unsupported browser versions are the most common root cause of otherwise-unexplained rendering issues.")],
  ["Dark Mode Display Glitches", P("Occasional color-contrast or icon-visibility glitches in Dark Mode are usually resolved by a hard refresh, which reloads the current theme's stylesheet cleanly. If a specific custom field type or third-party embedded content (like a linked Google Drive file preview) doesn't render correctly in Dark Mode, this is a known limitation for a small number of embed types rather than a bug in your specific workspace — switching to Light Mode is the current workaround for those specific embeds.")],
  ["Keyboard Shortcuts Not Responding", P("Keyboard shortcuts are disabled while a text field (like a task description or comment box) has focus, by design, to avoid conflicting with normal typing — click outside any input field before using a shortcut. Confirm no browser extension is intercepting the same key combination (common with certain shortcut-manager or vim-emulation extensions). The full shortcut list is viewable in-app by pressing ? (Shift+/), which also confirms whether shortcuts are functioning at all.")],
  ["Duplicate Notifications Being Sent", P("Duplicate notifications for the same event are most often caused by having the same notification type enabled across multiple channels (email, in-app, and mobile push) without realizing each fires independently for the same underlying event — this is expected behavior, not a bug, and can be adjusted under Account Settings > Notifications by disabling redundant channels. True duplicate notifications within the same channel (two identical emails) typically indicate an automation rule that's configured to trigger on the same condition more than once — review Project Settings > Automations for overlapping rules.")],
  ["Missing Tasks After Import", P("If tasks appear missing after a CSV or Asana/Trello import, first check the import summary report (available from Workspace Settings > Import > Import History) for any rows flagged as failed — these are the most common reason for a lower-than-expected task count, and the report lists the specific validation reason per failed row (commonly a missing required field or an invalid date format). Also confirm you're viewing the correct project; large imports occasionally get mapped to an unintended target project if it wasn't explicitly selected during setup.")],
  ["Export Getting Stuck or Timing Out", P("Large exports (thousands of tasks with attachments) are processed asynchronously and can take up to a few hours — this is expected, not a failure, and you'll receive an email with the download link once ready rather than needing to wait on the page. If an export has been pending for more than 24 hours with no completion email, check Workspace Settings > Privacy > Export My Data for its status; a status of Failed rather than Processing indicates a genuine issue, at which point contact Support with the export request timestamp.")],
  ["Integration Sync Delay with Slack", P("Slack notifications typically post within seconds of the triggering event. A sustained delay (more than a minute) usually indicates Slack-side rate limiting on their Events API, which self-resolves without any action needed on your end. If delays persist beyond 10 minutes consistently, check Workspace Settings > Integrations > Slack for a connection health warning, and confirm the Nimbus Workspace Slack app hasn't been rate-limited at the Slack workspace level by an overly aggressive third-party Slack app also installed there.")],
  ["Webhook Not Firing After Task Update", P("If a configured webhook isn't firing, first confirm the webhook is enabled and subscribed to the correct event type under Workspace Settings > Developer > Webhooks — a webhook subscribed only to task.created won't fire on an update. Check the Delivery Log for the specific event; if it shows as attempted but failed, review the returned status code, since your endpoint must return a 2xx response within 10 seconds for delivery to be marked successful (see Common Webhook Delivery Failures for detail).")],
  ["Custom Field Values Disappearing", P("A custom field value that appears to disappear is most often actually just hidden from the current view via the Fields visibility toggle (see Customizing Task Fields) rather than genuinely cleared — check whether the field is simply hidden before assuming data loss. If a Dropdown-type custom field's value is genuinely blank, confirm the previously selected option wasn't deleted from the field's configuration, since removing a dropdown option clears it from any task that had it selected.")],
  ["Unable to Delete a Project", P("If Delete Project is greyed out or fails, confirm your role has delete permission — only Admins and the designated Project Owner can delete a project by default. A project under an active Legal Hold (Enterprise) cannot be deleted until the hold is lifted, regardless of role, and will show a specific Legal Hold notice rather than a generic permission error. If you have the correct role and no hold applies, try archiving first (a lesser action) to confirm basic project-modification permissions are working at all.")],
  ["Guest User Can't Access Shared Project", P("If an invited guest reports they can't access a shared project, first confirm the invite was actually accepted — a pending invitation grants no access until accepted, visible under Team Directory > Pending Invitations. Confirm the guest is using the same email address the invite was sent to; a guest attempting to log in with a different email won't be recognized as the invited user. Also confirm the project's sharing settings weren't since revoked under Project Settings > Permissions.")],
  ["Video/Screen Recording Attachments Won't Play", P("Video attachments over 250MB will fail to upload rather than fail to play — confirm the file was fully uploaded first by checking it shows a complete thumbnail rather than a processing spinner. For videos that uploaded successfully but won't play, confirm the file format is one of the supported types (MP4, MOV, WebM); other formats will display as a downloadable file rather than an inline player, which is expected behavior rather than a playback bug.")],
  ["Push Notifications Not Working on Mobile", P("Confirm push notifications are enabled at both the app level (Nimbus Workspace app Settings > Notifications) and the OS level (device Settings > Notifications > Nimbus Workspace) — an OS-level permission revoked outside the app silently blocks all push delivery with no in-app error shown. On iOS, also confirm Focus modes or Do Not Disturb aren't suppressing notifications system-wide. Reinstalling the app re-triggers the OS notification permission prompt if it was previously dismissed without granting access.")],
  ["App Freezing When Switching Views", P("Occasional brief freezing when switching between List, Board, and Gantt views on a very large project (several thousand tasks) is a known performance characteristic tied to view re-rendering, not a bug — applying a filter to reduce visible task count before switching views significantly improves this. Persistent freezing on smaller projects, or freezing that doesn't resolve after a few seconds, is not expected — try a hard browser refresh, and if it recurs, contact Support with the specific project size and view combination.")],
  ["Recurring Task Creating Duplicates", P("If a recurring task is generating more than one new instance per cycle, check whether the recurrence rule was accidentally set up twice — opening the original task's due date field will show if Make Recurring was applied more than once, which can happen if a browser tab was left open and the action submitted twice. Remove the duplicate recurrence rule, keeping only one, and delete any already-generated duplicate instances manually; this won't affect the correctly configured recurrence going forward.")],
  ["Wrong Time Zone Displayed on Due Dates", P("Due dates display in each individual user's own profile time zone setting (Account Settings > Profile > Time Zone), not the workspace default or the time zone of whoever created the task — this is by design so a global team each sees accurate local deadlines, but it means two people can correctly see the same due date rendered at different clock times. Confirm your personal profile time zone is set correctly before assuming a display bug.")],
  ["Unable to Reorder Subtasks", P("Subtask reordering uses the same drag-and-drop mechanism as top-level tasks, and is subject to the same permission requirement — Guest-level access cannot reorder subtasks, by design. If you have edit permission and reordering still doesn't work, confirm you're dragging by the subtask's designated drag handle icon rather than clicking directly on the subtask text, which instead opens the subtask for editing rather than initiating a drag.")],
  ["Template Not Applying Correctly", P("If a project created from a template is missing expected structure (custom fields, saved views), confirm the template itself still has that structure — templates can be edited after creation, and a project created from an older version of a template won't retroactively pick up later template changes. If a genuinely current template applies incompletely, try recreating the project from the template again; a partial application usually indicates a page was closed mid-creation rather than a persistent template defect.")],
  ["SSO Login Failing After Password Change", P("On an SSO-enabled workspace, your Nimbus Workspace password is not used for login at all — authentication happens entirely through your identity provider (Okta, Azure AD, etc.). If login fails after changing a password, confirm you changed it with your identity provider (IT department), not through any Nimbus Workspace password field, since Nimbus Workspace-side password resets have no effect on SSO-enforced accounts. Contact your IT team if the identity provider password change itself is the issue.")],
  ["Report Data Doesn't Match Dashboard", P("A discrepancy between a generated Status Report and a live dashboard view is usually a timing difference — reports capture a point-in-time snapshot at generation, while dashboards reflect live data that may have changed since. Regenerate the report to compare against current dashboard data rather than assuming a calculation error. If numbers still don't reconcile after regenerating, confirm both are scoped to the same filter set (e.g., the report excluding archived tasks while the dashboard includes them, or vice versa).")],
  ["High CPU Usage from Desktop App", P("Sustained high CPU usage from the desktop app is most commonly caused by a very large project's Gantt view being left open in the background, which continues background layout calculations. Closing unused project tabs, especially Gantt views, typically resolves it immediately. If high CPU usage persists even with no large projects open, try fully quitting and relaunching the desktop app, and confirm you're on the latest version, since performance fixes are shipped regularly.")],
  ["Unable to Print a Project View", P("Printing directly from the browser's print function can render Board and Gantt views poorly, since they're not optimized for print layout — use Export > PDF instead (see Exporting a Project as PDF), which generates a print-optimized layout specifically designed for physical printing or PDF distribution, rather than relying on the browser's generic print-to-PDF handling of the live interactive view.")],
  ["Error Message: \"Something Went Wrong\" on Save", P("This generic error indicates the save request failed server-side without a more specific reason surfaced to the client, typically due to a brief connectivity blip or a temporary server-side issue. First, retry the save once — most instances resolve on retry. If it recurs specifically when saving a particular field or task, note the exact field and try a hard browser refresh before retrying again. If the error persists across multiple attempts and tasks, check status.nimbusworkspace.com, then contact Support with the approximate time of the failed save.")],
];

const SECURITY = [
  ["Account Security & Suspicious Activity", P("If you notice a login from an unfamiliar location or device in your login notifications:") + OL(["Change your password immediately from Account Settings > Security.","Go to Active Sessions and click Sign Out of All Devices to terminate any unauthorized session.","Enable Two-Factor Authentication if it isn't already on.","Review the Audit Log (Business/Enterprise) for any changes made during the suspicious session.","Contact Security Support at security@nimbusworkspace.com if you believe your account data was accessed or altered without authorization."])],
  ["What to Do If You See an Unrecognized Login", P("An unrecognized-login email notification includes the approximate location, device type, and time of the sign-in. If you don't recognize it, change your password right away and review Active Sessions to revoke it directly. If you do recognize the login but simply didn't expect the notification (a new device, a VPN changing your apparent location), no action is needed — this notification is a routine security measure, not necessarily a sign of compromise.")],
  ["Setting Up Login Alerts", P("Login alert emails for new devices or locations are enabled by default and cannot be fully disabled for individual users, since they're a core account-security feature. Business and Enterprise Admins can additionally configure alerts to also copy a shared security inbox for all workspace logins, under Workspace Settings > Security > Login Alerts:") + OL(["Go to Workspace Settings > Security > Login Alerts.","Toggle on Copy Admins on New Device Logins.","Select which Admin roles receive the copy.","Optionally set a threshold (e.g., only alert on logins from a new country, not just a new device).","Save — alerts apply to all users workspace-wide going forward."])],
  ["Understanding Nimbus Workspace's Security Architecture", P("Nimbus Workspace is built on a multi-tenant cloud architecture with logical data isolation per workspace, AES-256 encryption at rest, TLS 1.2+ in transit, and role-based access control enforced at the API layer for every request, not just the UI. Infrastructure runs on a major cloud provider with SOC 2-compliant data centers. A detailed architecture overview is available to Business and Enterprise customers under NDA — request it via Workspace Settings > Compliance > Security Documentation.")],
  ["Reporting a Security Vulnerability", P("If you discover a potential security vulnerability, report it responsibly to security@nimbusworkspace.com with as much detail as possible (steps to reproduce, affected component, potential impact) rather than testing further against production data or disclosing it publicly. Nimbus Workspace acknowledges reports within 24 hours and provides regular status updates until resolution, consistent with our published Responsible Disclosure Policy.")],
  ["Understanding the Bug Bounty Program", P("Nimbus Workspace runs a bug bounty program for qualifying security researchers, with reward tiers based on severity (using a standard CVSS-based scoring approach) and scope limited to production systems explicitly listed in the program's published rules at nimbusworkspace.com/security/bug-bounty. Testing against other customers' live data, denial-of-service testing, and social engineering are explicitly out of scope and excluded from reward eligibility.")],
  ["Enforcing 2FA Organization-Wide", P("Business and Enterprise Admins can require all users to enable 2FA rather than leaving it optional:") + OL(["Go to Workspace Settings > Security > Two-Factor Authentication.","Toggle on Require 2FA for All Users.","Set a grace period (recommended: 7 days) during which users are prompted but not yet blocked.","After the grace period, users without 2FA configured are blocked from login until they set it up.","SSO-authenticated users are exempt from this workspace-level 2FA requirement, since authentication is handled by the identity provider instead."])],
  ["Configuring SAML SSO with Okta", P("To connect Okta as your SAML identity provider:") + OL(["In Okta, create a new SAML 2.0 app integration.","Copy the Nimbus Workspace ACS URL and Entity ID (found under Workspace Settings > Security > Single Sign-On) into the Okta app configuration.","In Okta, configure attribute statements to pass email and name to Nimbus Workspace.","Download the Okta signing certificate and upload it into Nimbus Workspace's SSO configuration.","Test with a non-Admin test user before enabling Enforce SSO workspace-wide, to avoid locking out Admins if a mapping is misconfigured."])],
  ["Configuring SAML SSO with Azure AD", P("To connect Azure AD (Microsoft Entra ID) as your SAML identity provider:") + OL(["In Azure AD, create a new Enterprise Application using the non-gallery SAML option.","Enter the Nimbus Workspace ACS URL and Entity ID from Workspace Settings > Security > Single Sign-On.","Configure the SAML claims to map user.mail and user.displayname to the expected attributes.","Download the Azure AD Federation Metadata XML and upload it into Nimbus Workspace.","Assign the appropriate Azure AD user groups to the enterprise application, then test before enabling Enforce SSO."])],
  ["Configuring SAML SSO with Google Workspace", P("To connect Google Workspace as your SAML identity provider:") + OL(["In the Google Admin console, add a new custom SAML app.","Enter the Nimbus Workspace ACS URL and Entity ID from Workspace Settings > Security > Single Sign-On.","Download the Google IdP metadata and upload it into Nimbus Workspace's SSO configuration.","Map the standard email and name attributes in the Google Admin console's attribute mapping step.","Turn on the SAML app for the appropriate organizational unit in Google Admin, then test a login before enabling Enforce SSO."])],
  ["Understanding Session Management Security", P("Nimbus Workspace issues a short-lived session token on login, refreshed silently in the background as long as you remain active, and fully expiring after the configured idle timeout (24 hours by default, adjustable by Enterprise Admins). Session tokens are bound to the originating device fingerprint, so a stolen token used from a substantially different device/browser combination triggers an additional verification challenge rather than being honored automatically.")],
  ["Locking an Account After Suspicious Activity", P("Admins can immediately lock a specific user's account (distinct from deactivation) if suspicious activity is suspected, blocking login instantly while preserving all account data and settings for investigation. Go to Team Directory, find the user, and select Lock Account from the action menu. A locked account can only be unlocked by an Admin after reviewing the Audit Log for that user's recent activity, or by Nimbus Workspace Support if the Admin's own account is the one in question.")],
  ["Reviewing the Security Audit Log", P("The Security Audit Log (Business/Enterprise) under Workspace Settings > Security > Audit Log records logins (including failures), password changes, role changes, SSO/2FA configuration changes, and data exports, each with a timestamp, actor, and source IP. Filter by user, event type, or date range, and export any filtered view to CSV for offline review or submission to an external security team during an investigation.")],
  ["Setting IP-Based Access Restrictions", P("See Restricting Login by IP Address for the full setup steps under Workspace Settings > Security > IP Allowlist. From a security-policy standpoint, this control is most effective combined with SSO enforcement, since it restricts both the network location and the identity provider through which access is possible, meaningfully narrowing the attack surface for account takeover attempts even if a password or session token were compromised.")],
  ["Understanding Data Encryption Standards", P("See Understanding Data Encryption at Rest and in Transit for full detail — in summary, AES-256 at rest and TLS 1.2+ in transit, applied uniformly across all plan tiers, with keys managed through a dedicated key management service and rotated automatically on an annual schedule. Encryption standards are documented in full in the SOC 2 report available to Business and Enterprise customers under NDA.")],
  ["Reviewing Nimbus Workspace's Trust and Status Page", P("The Trust Center at trust.nimbusworkspace.com consolidates security documentation, current compliance certifications, the sub-processor list, and links to request the SOC 2 report or penetration test summary under NDA. It's separate from status.nimbusworkspace.com, which covers real-time system uptime and incident history rather than security/compliance posture — check the Trust Center first for any vendor security-review or procurement questionnaire.")],
  ["Understanding Role-Based Access Control (RBAC)", P("Access in Nimbus Workspace is enforced through role-based permissions at every layer — UI, API, and integrations all check the same underlying role/permission model, so a Guest-level API token cannot bypass restrictions the UI also enforces. Standard roles (Owner, Admin, Member, Guest) cover most needs; Business and Enterprise custom roles allow more granular permission combinations where the four standard roles don't fit an organization's structure precisely.")],
  ["Setting Up Approved Device Lists (Enterprise)", P("Enterprise plans can restrict login to a list of approved device fingerprints (in addition to, not instead of, IP allowlisting) for organizations requiring managed-device-only access:") + OL(["Go to Workspace Settings > Security > Approved Devices.","Enable Require Approved Devices.","Have each user register their device on first login after enabling, which requires Admin approval.","Review and approve pending device registrations from the same screen.","Any login attempt from an unapproved device is blocked with an explanatory message, regardless of correct password and 2FA."])],
  ["Understanding Phishing Protection Measures", P("Nimbus Workspace enforces SPF, DKIM, and DMARC on all outbound system email to make spoofed \"from Nimbus Workspace\" phishing emails easier for receiving mail servers to reject automatically. All legitimate password reset and security emails link only to nimbusworkspace.com domains — Nimbus Workspace never asks for your password via email or embeds a login form directly inside an email. Report any suspicious email claiming to be from Nimbus Workspace to security@nimbusworkspace.com.")],
  ["Reporting a Phishing Email Impersonating Nimbus", P("If you receive a suspicious email impersonating Nimbus Workspace (asking you to \"verify your account\" via an unfamiliar link, for example), do not click any links or enter credentials. Forward the full email, including headers, to security@nimbusworkspace.com. Our security team investigates reported phishing campaigns and, where possible, works with hosting providers to have malicious lookalike domains taken down.")],
  ["Understanding Password Complexity Requirements", P("The platform-wide minimum password requirement is 8 characters including at least one number, applicable to all non-SSO accounts. Business and Enterprise Admins can strengthen this under Workspace Settings > Security > Password Policy, requiring up to 20 characters with mandatory uppercase, symbol, and periodic expiration rules (see Setting a Password Policy for Your Organization). SSO-enabled accounts have no Nimbus Workspace-side password at all, so this policy doesn't apply to them.")],
  ["Setting a Maximum Session Duration", P("Beyond the idle timeout (see Session Timeout Settings), Enterprise Admins can also set an absolute maximum session duration under Workspace Settings > Security > Session Policy — for example, forcing re-authentication every 8 hours regardless of activity level, which is stricter than an idle-only timeout and often required by regulated industries. This setting works alongside, not instead of, the idle timeout; whichever limit is reached first ends the session.")],
  ["Understanding Multi-Factor Authentication Options", P("Two 2FA methods are supported: a TOTP authenticator app (recommended, works offline, compatible with any standard authenticator like Google Authenticator or Authy) and SMS text message (simpler to set up but vulnerable to SIM-swapping attacks, and requires cellular signal). Enterprise Admins can restrict which method(s) are permitted workspace-wide under Workspace Settings > Security > Two-Factor Authentication, disabling SMS as an option if a stronger security posture is required.")],
  ["Reviewing Third-Party App Access", P("Go to Account Settings > Security > Connected Apps to see every OAuth application currently authorized to access your account, including the scopes each was granted and the date of authorization. Admins can view a workspace-wide equivalent under Workspace Settings > Security > Third-Party Access, covering every app any user in the workspace has authorized, which is useful for periodically auditing for apps that are no longer in active use.")],
  ["Revoking Access for a Connected App", P("To revoke a third-party app's access, go to Account Settings > Security > Connected Apps (or the workspace-wide equivalent for Admins reviewing another user's connections), find the app, and click Revoke Access. This immediately invalidates that app's OAuth token; if you want to reconnect the same app later, you'll need to go through its authorization flow again from scratch, since the original token cannot be reactivated once revoked.")],
  ["Understanding Data Loss Prevention Controls", P("See Configuring Data Loss Prevention Settings for setup steps. These Enterprise controls (restricting attachment types, disabling guest access workspace-wide, restricting bulk export to Admins) are preventive, additive restrictions layered on top of standard RBAC — they narrow what's possible beyond a user's role permissions, and cannot be used to grant additional access beyond what a role already allows.")],
  ["Setting Up Security Alerts for Admins", P("Beyond login notifications to individual users, Admins can configure proactive security alerts for workspace-wide events under Workspace Settings > Security > Admin Alerts — for example, a new Admin role assignment, a bulk data export, or an SSO/2FA configuration change. Alerts can be delivered by email or, if Slack/Teams is connected, posted directly to a designated security channel for faster visibility than email alone.")],
  ["Understanding SOC 2 Type II Compliance", P("SOC 2 Type II evaluates not just the design of security controls but their operating effectiveness over a sustained observation period (typically 6–12 months), audited by an independent third-party firm. Nimbus Workspace's report covers the Security, Availability, and Confidentiality trust service criteria and is renewed annually. See Requesting a SOC 2 Report for how to obtain the current report under NDA.")],
  ["Understanding ISO 27001 Certification Status", P("Nimbus Workspace's current ISO 27001 certification status, along with the scope of certification and the certifying body, is published on the Trust Center at trust.nimbusworkspace.com and updated whenever certification is renewed or the scope changes. If ISO 27001 is a specific procurement requirement for your organization, confirm current status there rather than relying on historical documentation, since certification scope can evolve between renewal cycles.")],
  ["Reviewing the Responsible Disclosure Policy", P("The full Responsible Disclosure Policy at nimbusworkspace.com/security/disclosure outlines expected researcher conduct (no testing against other customers' data, no public disclosure before a fix is available), our commitment to acknowledge reports within 24 hours, and typical remediation timelines by severity. Researchers following this policy in good faith are given safe-harbor assurance against legal action for their testing activity, as detailed in the policy.")],
  ["Understanding Insider Threat Monitoring", P("Nimbus Workspace's internal access to customer data is logged and subject to least-privilege principles — employee access to production customer data requires a specific, time-boxed, and logged justification, reviewed periodically by our security team. This internal monitoring is distinct from the customer-facing Audit Log, which tracks activity within your own workspace by your own users, not Nimbus Workspace employee access to the underlying infrastructure.")],
  ["Setting Up Just-in-Time Provisioning with SSO", P("With SAML SSO configured, Enterprise workspaces can enable Just-in-Time (JIT) provisioning so a new user is automatically created in Nimbus Workspace on their very first successful SSO login, without needing to be pre-invited manually. Enable this under Workspace Settings > Security > Single Sign-On > JIT Provisioning, and set a default role for JIT-created users. This is distinct from full SCIM provisioning, which also handles automatic deprovisioning; JIT alone only handles creation.")],
  ["Understanding Encryption Key Management", P("Encryption keys used for AES-256 at-rest encryption are managed through a dedicated cloud key management service, separate from the application layer that uses them, with automatic annual rotation and strict access logging on any key-management operation. Enterprise customers requiring customer-managed encryption keys (a \"bring your own key\" model) should discuss feasibility with their account executive, as this is evaluated as a custom Enterprise arrangement rather than a standard offering.")],
  ["Reviewing Login History for Your Account", P("Go to Account Settings > Security > Login History to see every login to your account over the past 90 days, including timestamp, approximate location, device type, and whether it was via password, SSO, or a linked Google/Microsoft account. This is a personal, read-only history distinct from the workspace-wide Security Audit Log available to Admins, and is a useful first check if you suspect unauthorized access.")],
  ["Understanding Account Lockout Thresholds", P("After 5 consecutive failed login attempts within a 15-minute window, an account is temporarily locked for 15 minutes as a brute-force protection measure, with an email notification sent describing the lockout. This threshold is fixed and not configurable on Team or Business plans; Enterprise Admins can adjust the failed-attempt threshold and lockout duration under Workspace Settings > Security > Account Lockout Policy.")],
  ["Setting Up Security Contact Notifications", P("Business and Enterprise workspaces can designate a security contact (a role-based email like security@yourcompany.com, distinct from any individual user account) to receive copies of security-relevant notifications — new Admin assignments, SSO configuration changes, bulk exports — under Workspace Settings > Security > Security Contact. This ensures continuity of security oversight even if the individual Admin who configured a setting later leaves the organization.")],
  ["Understanding Vulnerability Disclosure Timelines", P("Once a reported vulnerability is confirmed, Nimbus Workspace's internal target is to remediate critical-severity issues within 7 days, high-severity within 30 days, and medium/low-severity within 90 days, with the reporting researcher updated at each significant milestone. These are internal targets published for transparency in the Responsible Disclosure Policy, not contractual SLAs, though Enterprise customers with specific security-response SLA requirements can discuss custom terms through their account executive.")],
  ["Reviewing Nimbus Workspace's Penetration Testing Cadence", P("Nimbus Workspace commissions an independent third-party penetration test at least annually, covering the production application, API, and supporting infrastructure, in addition to continuous automated vulnerability scanning between formal tests. An executive summary of the most recent test is available to Business and Enterprise customers under NDA — see Requesting a Penetration Test Summary for how to obtain it.")],
  ["Understanding Fraud Detection on Payment Methods", P("Payment processing includes automated fraud screening (card verification, velocity checks on rapid repeated charge attempts, and geographic risk scoring) before a charge is authorized. A legitimate charge occasionally flagged as suspicious by this screening will show as declined even with correct card details — if you believe a decline was a false positive, contact your card issuer first, since the actual authorization decision is made by their fraud systems, not Nimbus Workspace's.")],
  ["Setting Organization-Wide IP Allowlists", P("See Restricting Login by IP Address and IP Allowlisting for API Access for the two related but separate controls — one restricts interactive login, the other restricts API token usage. Enterprise organizations typically configure both together for a consistent network-boundary security posture, ensuring that neither the web/mobile login path nor programmatic API access is reachable from outside approved network ranges.")],
  ["Understanding Device Trust and Remembered Devices", P("When you complete 2FA successfully, you can choose Remember This Device for 30 days, skipping the 2FA prompt on subsequent logins from that same specific browser/device combination while still requiring your password each time. This trust is scoped narrowly to one browser on one device — a different browser on the same computer, or the same browser after being cleared of cookies, will require 2FA again. Admins can disable the Remember This Device option workspace-wide for stricter environments.")],
  ["Reporting a Compromised Account", P("If you believe your account has been compromised (unauthorized changes, logins you can't explain even after checking Login History), act immediately:") + OL(["Change your password right away from a device you trust.","Go to Active Sessions and select Sign Out of All Devices.","Enable or reset Two-Factor Authentication.","Review the Security Audit Log (or ask an Admin to) for any unauthorized changes made during the compromise window.","Email security@nimbusworkspace.com describing what you observed — our team can review server-side login and access logs beyond what's visible in your own Login History."])],
];

const DOMAINS = [
  ["Billing & Subscriptions", BILLING],
  ["Account & User Management", ACCOUNT],
  ["Workspace & Project Setup", WORKSPACE],
  ["Integrations & API", INTEGRATIONS],
  ["Data Import/Export & Compliance", COMPLIANCE],
  ["Troubleshooting", TROUBLESHOOTING],
  ["Security & Compliance", SECURITY],
];

// ---------- Build records ----------
function slugify(title) {
  return title
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

const seenSlugs = new Set();
function uniqueSlug(title) {
  let base = slugify(title);
  let slug = base;
  let n = 2;
  while (seenSlugs.has(slug)) {
    slug = `${base}-${n}`;
    n++;
  }
  seenSlugs.add(slug);
  return slug;
}

function csvEscape(value) {
  const s = String(value);
  return `"${s.replace(/"/g, '""')}"`;
}

const rows = [];
let total = 0;
for (const [domainLabel, articles] of DOMAINS) {
  for (const [title, body] of articles) {
    total++;
    rows.push({
      Title: title,
      UrlName: uniqueSlug(title),
      Summary: body,
      Language: "en_US",
      IsVisibleInPkb: "TRUE",
      IsVisibleInCsp: "TRUE",
      IsVisibleInPrm: "FALSE",
      __domain: domainLabel,
    });
  }
}

const headers = ["Title", "UrlName", "Summary", "Language", "IsVisibleInPkb", "IsVisibleInCsp", "IsVisibleInPrm"];
const csvLines = [headers.join(",")];
for (const r of rows) {
  csvLines.push(headers.map((h) => csvEscape(r[h])).join(","));
}

const outDir = path.join(__dirname, "..");
const outFile = path.join(outDir, "Nimbus_Knowledge_Articles.csv");
fs.writeFileSync(outFile, csvLines.join("\r\n"), "utf8");

// Per-domain counts for verification
const counts = {};
for (const r of rows) counts[r.__domain] = (counts[r.__domain] || 0) + 1;

console.log(`Wrote ${rows.length} article records to ${outFile}`);
console.log("Per-domain counts:");
for (const [domain, articles] of DOMAINS) {
  console.log(`  ${domain}: ${counts[domain]}`);
}
console.log(`Unique UrlNames: ${seenSlugs.size}`);
